styles:
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg: #f7f7f5; --surface: #ffffff; --border: #e8e8e4;
      --text-primary: #1a1a1a; --text-secondary: #6b6b6b; --text-muted: #a0a0a0;
      --accent: #2563eb; --green: #16a34a; --green-soft: #f0fdf4;
      --red: #dc2626; --red-soft: #fef2f2; --amber: #d97706; --amber-soft: #fffbeb;
      --radius: 10px;
      --shadow: 0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,.08);
    }
    body { background: var(--bg); color: var(--text-primary); min-height: 100vh;
           font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
           overflow-x: hidden; }
    canvas { max-width: 100%; }

    /* Header — 2 linhas internas (.header-row-top só existe no mobile: hambúrguer +
       ícone da marca; .header-row-controls é a linha "real" com os controles,
       sempre visível, alinhada à direita como na referência nena-ops). */
    header { background: var(--surface); border-bottom: 1px solid var(--border);
             padding: 0 28px; display: flex; flex-direction: column; justify-content: center;
             position: sticky; top: 0; z-index: 100; }
    .header-row-top { display: none; align-items: center; justify-content: space-between; }
    .header-row-controls { display: flex; align-items: center; justify-content: flex-end;
                            gap: 22px; height: 56px; }

    .logo { display: none; align-items: center; justify-content: center;
            text-decoration: none; flex-shrink: 0; }
    .logo-icon { width: 28px; height: 28px; background: var(--accent); border-radius: 7px;
                 display: flex; align-items: center; justify-content: center; color: white;
                 font-size: 12px; font-weight: 800; letter-spacing: -.5px; }
    .header-controls { display: flex; align-items: center; gap: 8px; flex-wrap: nowrap; }
    .header-actions  { display: flex; align-items: center; gap: 14px; flex-shrink: 0; }

    /* Refresh/theme — ícones soltos, sem caixa, igual à referência */
    .refresh-btn { background: none; border: none; padding: 4px; cursor: pointer;
      color: var(--text-muted); display: flex; align-items: center; justify-content: center;
      transition: color .15s; flex-shrink: 0; }
    .refresh-btn:hover { color: var(--accent); }
    @keyframes spin-refresh { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
    .refresh-btn.loading svg { animation: spin-refresh .7s linear infinite; }

    /* Avatar do usuário (decorativo — sem sistema de login) */
    .user-avatar { width: 30px; height: 30px; border-radius: 50%; background: var(--text-primary);
      color: #fff; display: flex; align-items: center; justify-content: center;
      font-size: 12px; font-weight: 700; letter-spacing: -.2px; flex-shrink: 0; }

    /* Mobile header
       Linha 1 (.header-row-top): hambúrguer (esquerda) + marca (direita)
       Linha 2 (.header-row-controls): pills de filtro + status, em scroll horizontal se precisar */
    @media (max-width: 600px) {
      header { padding: 10px 14px; gap: 10px; }
      .header-row-top { display: flex; }
      .logo { display: flex; }
      .header-row-controls {
        height: auto; justify-content: flex-start; gap: 8px;
        flex-wrap: nowrap; overflow-x: auto; -webkit-overflow-scrolling: touch;
        scrollbar-width: none;
      }
      .header-row-controls::-webkit-scrollbar { display: none; }
      .header-controls { flex-shrink: 0; }
      .header-actions { flex-shrink: 0; }
      .filter-select, .date-picker-btn { flex-shrink: 0; }
      #dateRangeHint  { display: none; }
      #freshnessWrap  { display: none; }
      main { padding: 14px 10px 40px; }
      .kpi-value { font-size: 16px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
      .kpi-card { padding: 12px 10px 10px; }
      .kpi-top { flex-direction: column-reverse; align-items: flex-start; gap: 3px; }
      .kpi-label { white-space: normal; overflow: visible; text-overflow: clip; }
      .grid-2-1, .grid-1-1 { grid-template-columns: 1fr; }
      .gauge-row { grid-template-columns: repeat(2, 1fr); }
      .dow-grid { grid-template-columns: repeat(4, 1fr); }
    }

    /* Filters — pills arredondadas (rounded-full), igual à referência */
    .filter-select {
      appearance: none;
      background: var(--surface) url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5 5L9 1' stroke='%236b6b6b' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") no-repeat right 12px center;
      border: 1px solid var(--border); border-radius: 999px; padding: 8px 30px 8px 14px;
      font-size: 13px; font-weight: 500; color: var(--text-primary); cursor: pointer; outline: none; }
    .filter-select:hover, .filter-select:focus { border-color: var(--accent); }

    .date-picker-wrapper { position: relative; }
    .date-picker-btn { display: flex; align-items: center; gap: 7px; background: var(--surface);
      border: 1px solid var(--border); border-radius: 999px; padding: 8px 14px;
      font-size: 13px; font-weight: 500; color: var(--text-primary); cursor: pointer; white-space: nowrap; outline: none; }
    .date-picker-btn:hover { border-color: var(--accent); }
    .date-dropdown { display: none; position: absolute; right: 0; top: calc(100% + 6px);
      background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
      box-shadow: var(--shadow-md); z-index: 200; min-width: 240px; overflow: hidden; }
    @media (max-width: 600px) {
      .date-dropdown { position: fixed; top: auto; left: 10px; right: 10px;
        width: auto; min-width: unset; border-radius: 12px;
        /* position below the header bar */ margin-top: 0; }
    }
    .date-dropdown.open { display: block; }
    .date-presets { padding: 6px; display: flex; flex-direction: column; gap: 1px; }
    .date-preset { padding: 7px 10px; font-size: 12.5px; border-radius: 6px; cursor: pointer;
      color: var(--text-secondary); display: flex; align-items: center; justify-content: space-between; }
    .date-preset:hover { background: var(--bg); color: var(--text-primary); }
    .date-preset.active { background: #eff6ff; color: var(--accent); font-weight: 600; }
    .date-divider { height: 1px; background: var(--border); margin: 4px 0; }
    .date-custom { padding: 10px; display: none; flex-direction: column; gap: 8px; border-top: 1px solid var(--border); }
    .date-custom.visible { display: flex; }
    .date-custom label { font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase; }
    .date-custom input[type="date"] { border: 1px solid var(--border); border-radius: 6px;
      padding: 5px 8px; font-size: 12.5px; color: var(--text-primary); outline: none; width: 100%; }
    .date-apply { background: var(--accent); color: white; border: none; border-radius: 6px;
      padding: 7px 14px; font-size: 12.5px; font-weight: 600; cursor: pointer; width: 100%; }
    .date-apply:hover { background: #1d4ed8; }

    /* Layout */
    main { max-width: 1360px; margin: 0 auto; padding: 24px 28px 60px; }
    .section-label { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase;
                     color: var(--text-muted); margin-bottom: 12px; margin-top: 28px; }
    .section-label:first-child { margin-top: 0; }

    /* Título/subtítulo de página — mesmo padrão do tracking-gateway.html */
    .page-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 20px; }
    .page-title { font-size: 21px; font-weight: 700; }
    .page-subtitle { font-size: 12.5px; color: var(--text-secondary); margin-top: 6px; }

    /* KPI Rows — stretch makes all cards in a row the same height */
    .kpi-row { display: grid; gap: 10px; margin-bottom: 10px; align-items: stretch; }
    .kpi-row-1 { grid-template-columns: repeat(5, 1fr); }
    .kpi-row-2 { grid-template-columns: repeat(5, 1fr); }
    .kpi-row-3 { grid-template-columns: repeat(5, 1fr); }
    @media (max-width: 1400px) { .kpi-row-1 { grid-template-columns: repeat(5, 1fr); } .kpi-row-2 { grid-template-columns: repeat(5, 1fr); } .kpi-row-3 { grid-template-columns: repeat(5, 1fr); } }
    @media (max-width: 1200px) { .kpi-row-1 { grid-template-columns: repeat(3, 1fr); } .kpi-row-2 { grid-template-columns: repeat(3, 1fr); } .kpi-row-3 { grid-template-columns: repeat(3, 1fr); } }
    @media (max-width: 700px)  { .kpi-row-1, .kpi-row-2, .kpi-row-3 { grid-template-columns: repeat(2, 1fr); } }
    /* Último card em linha ímpar (5º de 5) ocupa largura total para não deixar lacuna */
    @media (max-width: 700px)  { .kpi-row .kpi-card:last-child:nth-child(odd) { grid-column: 1 / -1; } }

    .kpi-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
      padding: 16px 16px 12px; box-shadow: var(--shadow); position: relative; overflow: visible;
      transition: box-shadow .15s, transform .15s; min-width: 0; }
    .kpi-card:hover { box-shadow: var(--shadow-md); transform: translateY(-1px); }
    .kpi-top { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 5px; gap: 4px; }
    .kpi-label { font-size: 11.5px; color: var(--text-secondary); font-weight: 500; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .badge { display: inline-flex; align-items: center; gap: 2px; font-size: 10.5px; font-weight: 700; white-space: nowrap; flex-shrink: 0;
             border-radius: 4px; padding: 2px 5px; flex-shrink: 0; }
    .badge.up      { background: var(--green-soft); color: var(--green); }
    .badge.down    { background: var(--red-soft);   color: var(--red); }
    .badge.neutral { background: var(--amber-soft); color: var(--amber); }
    .kpi-value { font-size: 22px; font-weight: 700; color: var(--text-primary);
                 line-height: 1; letter-spacing: -.03em; margin-bottom: 8px; }
    .kpi-value-secondary { font-size: 12px; font-weight: 300; color: var(--text-muted);
                 line-height: 1.2; letter-spacing: 0; margin: -5px 0 8px; }
    .kpi-value-secondary b { font-weight: 500; color: var(--text-secondary); }
    /* Sparkline: fixed-height wrapper so Chart.js respects the bounds */
    .kpi-spark-wrap { height: 34px; position: relative; width: 100%; }
    .kpi-spark-wrap canvas { position: absolute; inset: 0; width: 100% !important; height: 100% !important; }
    .kpi-sub { font-size: 11px; color: var(--text-muted); margin-top: 5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .kpi-accent { position: absolute; bottom: 0; left: 0; right: 0; height: 3px; }
    .kpi-accent.blue  { background: var(--accent); }
    .kpi-accent.green { background: var(--green); }
    .kpi-accent.red   { background: var(--red); }
    .kpi-accent.amber { background: var(--amber); }
    .kpi-accent.purple{ background: #7c3aed; }
    /* KPI delta vs período anterior */
    .kpi-delta { font-size: 10.5px; font-weight: 600; margin-top: 2px; display: block; min-height: 14px; }
    .kpi-delta.pos { color: var(--green); }
    .kpi-delta.neg { color: var(--red); }
    .kpi-delta.neu { color: var(--text-muted); }
    .kpi-card.alert-pulse { border-color: #fca5a5 !important; box-shadow: 0 0 0 2px rgba(220,38,38,.12) !important; }

    /* ── Cards de monitoramento (Google Ads + Bureau) ───────────────────── */
    .monitor-grid { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:16px; }
    @media(max-width:800px){ .monitor-grid { grid-template-columns:1fr; } }

    /* ── Saldo Google Ads ─────────────────────────────────────────────────── */
    .ads-balance-card { background:var(--surface); border:1px solid var(--border); border-radius:var(--radius);
      padding:16px 20px; transition:box-shadow .15s; }
    .ads-balance-card:hover { box-shadow:var(--shadow-md); }
    .ads-balance-top { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-bottom:14px; }
    .ads-balance-main { display:flex; align-items:center; gap:14px; }
    .ads-balance-label { font-size:11px; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:var(--text-muted); margin-bottom:3px; }
    .ads-balance-value { font-size:26px; font-weight:700; color:var(--text-primary); letter-spacing:-.5px; }
    .ads-balance-topright { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
    .ads-balance-badge { font-size:11px; font-weight:600; padding:3px 10px; border-radius:20px; }
    .ads-balance-badge.ok       { background:#dcfce7; color:#15803d; }
    .ads-balance-badge.aviso    { background:#fef9c3; color:#a16207; }
    .ads-balance-badge.atencao  { background:#ffedd5; color:#c2410c; }
    .ads-balance-badge.critico  { background:#fee2e2; color:#b91c1c; }
    .ads-balance-meta { font-size:10.5px; color:var(--text-muted); }
    .ads-balance-metrics { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; }
    @media(max-width:700px){ .ads-balance-metrics { grid-template-columns:repeat(2,1fr); } }
    .ads-bal-metric { background:var(--bg); border:1px solid var(--border); border-radius:8px; padding:10px 12px; }
    .ads-bal-metric-label { font-size:10.5px; color:var(--text-muted); font-weight:500; margin-bottom:4px; }
    .ads-bal-metric-value { font-size:16px; font-weight:700; color:var(--text-primary); }
    .ads-bal-metric-sub { font-size:10px; color:var(--text-muted); margin-top:2px; }
    .ads-bal-metric.warn .ads-bal-metric-value { color:#d97706; }
    .ads-bal-metric.danger .ads-bal-metric-value { color:#dc2626; }
    .ads-bal-metric.good .ads-bal-metric-value  { color:#16a34a; }
    .ads-balance-spark { display:flex; align-items:flex-end; gap:2px; height:24px; }
    .ads-balance-spark span { width:4px; border-radius:2px 2px 0 0; opacity:.75; min-height:2px; }
    .ads-balance-card.pulse-critico { border-color:#fca5a5 !important; animation:ads-pulse 2s infinite; }
    @keyframes ads-pulse { 0%,100%{box-shadow:0 0 0 2px rgba(220,38,38,.12)} 50%{box-shadow:0 0 0 5px rgba(220,38,38,.22)} }

    /* ── Bureau Assertiva card ────────────────────────────────────────────── */
    .bureau-card { background:var(--surface); border:1px solid var(--border); border-radius:var(--radius);
      padding:16px 20px; transition:box-shadow .15s; }
    .bureau-card:hover { box-shadow:var(--shadow-md); }
    .bureau-card-top { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-bottom:14px; }
    .bureau-card-main { display:flex; align-items:center; gap:14px; }
    .bureau-card-label { font-size:11px; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:var(--text-muted); margin-bottom:3px; }
    .bureau-card-value { font-size:26px; font-weight:700; color:var(--text-primary); letter-spacing:-.5px; }
    .bureau-card-badge { font-size:11px; font-weight:600; padding:3px 10px; border-radius:20px; }
    .bureau-card-badge.ok     { background:#dcfce7; color:#15803d; }
    .bureau-card-badge.aviso  { background:#fef9c3; color:#a16207; }
    .bureau-card-badge.spike  { background:#ffedd5; color:#c2410c; }
    .bureau-card-meta { font-size:10.5px; color:var(--text-muted); }
    .bureau-card-spark { display:flex; align-items:flex-end; gap:2px; height:24px; }
    .bureau-card-spark span { width:4px; border-radius:2px 2px 0 0; opacity:.75; min-height:2px; }

    /* ── Bureau por Tipo (Assertiva vs CheckTudo) ─────────────────────────── */
    .bureau-type-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:4px; }
    @media(max-width:700px){ .bureau-type-grid { grid-template-columns:1fr; } }
    .bureau-type-item { background:var(--bg); border:1px solid var(--border); border-radius:8px; padding:12px 14px; }
    .bureau-type-name { font-size:10.5px; font-weight:700; letter-spacing:.05em; text-transform:uppercase; color:var(--text-muted); margin-bottom:4px; }
    .bureau-type-value { font-size:19px; font-weight:700; color:var(--text-primary); }
    .bureau-type-sub { font-size:10.5px; color:var(--text-muted); margin-top:3px; }
    .bureau-type-bar { height:5px; border-radius:3px; background:var(--border); margin-top:8px; overflow:hidden; }
    .bureau-type-bar-fill { height:100%; border-radius:3px; }

    /* Day-of-week — desktop grid 2 linhas (4+3), mobile carousel */
    .dow-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 8px;
                align-items: stretch; }
    .dow-cell { align-self: stretch; display: flex; flex-direction: column; justify-content: space-between; }
    .dow-cell { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
                padding: 12px 8px; text-align: center; box-shadow: var(--shadow); }
    .dow-day  { font-size: 10px; font-weight: 700; color: var(--text-muted); text-transform: uppercase;
                letter-spacing: .05em; margin-bottom: 6px; }
    .dow-val  { font-size: 14.5px; font-weight: 700; }
    .dow-sub  { font-size: 10.5px; color: var(--text-muted); margin-top: 3px; }
    .dow-badge { display: inline-block; font-size: 9.5px; font-weight: 700; border-radius: 3px;
                 padding: 1px 5px; margin-top: 5px; }
    .dow-best  { background: var(--green-soft); border-color: #86efac; }
    .dow-worst { background: var(--red-soft);   border-color: #fca5a5; }
    .dow-badge.best  { background: #dcfce7; color: #15803d; }
    .dow-badge.worst { background: #fee2e2; color: #b91c1c; }
    /* Carousel dots — only visible on mobile */
    .dow-dots { display: none; }
    @media (max-width: 700px) {
      .dow-grid { display: flex; gap: 8px; overflow-x: auto; scroll-snap-type: x mandatory;
                  -webkit-overflow-scrolling: touch; padding-bottom: 4px;
                  scrollbar-width: none; }
      .dow-grid::-webkit-scrollbar { display: none; }
      .dow-cell { flex: 0 0 calc(33% - 6px); min-width: 96px; scroll-snap-align: start; }
      .dow-dots { display: flex; justify-content: center; align-items: center;
                  gap: 5px; margin-top: 8px; }
      .dow-dot  { width: 6px; height: 6px; border-radius: 50%;
                  background: var(--border); transition: background .2s, transform .2s; }
      .dow-dot.active { background: var(--accent); transform: scale(1.3); }
    }

    /* Freshness dot */
    .fresh-dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; flex-shrink: 0; }
    .fresh-dot.green  { background: var(--green); }
    .fresh-dot.amber  { background: var(--amber); }
    .fresh-dot.red    { background: var(--red);   }
    #freshnessWrap { display: flex; align-items: center; gap: 5px; font-size: 11.5px; color: var(--text-muted); }

    /* Today Pace */
    .pace-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
                 padding: 18px 20px; box-shadow: var(--shadow); margin-bottom: 12px; }
    .pace-header { display: flex; align-items: center; justify-content: space-between;
                   margin-bottom: 16px; flex-wrap: wrap; gap: 8px; }
    .pace-title  { font-size: 11px; font-weight: 700; color: var(--text-muted);
                   text-transform: uppercase; letter-spacing: .08em; }
    .pace-status { font-size: 13px; font-weight: 700; }
    .pace-grid   { display: grid; grid-template-columns: repeat(3, 1fr);
                   gap: 0; margin-bottom: 16px; }
    .pace-stat   { display: flex; flex-direction: column; gap: 3px;
                   padding: 12px 16px; border-right: 1px solid var(--border);
                   border-bottom: 1px solid var(--border); }
    .pace-stat:nth-child(3n)  { border-right: none; }
    .pace-stat:nth-last-child(-n+3) { border-bottom: none; }
    .pace-lbl    { font-size: 10px; color: var(--text-muted); font-weight: 600;
                   text-transform: uppercase; letter-spacing: .05em; line-height: 1.2;
                   min-height: 2.4em; display: flex; align-items: flex-start; }
    .pace-val    { font-size: 17px; font-weight: 700; line-height: 1.2; margin-top: 2px; }
    .pace-sub    { font-size: 10.5px; color: var(--text-muted); margin-top: 1px; }
    .pace-bar-wrap { padding: 4px 0 0; }
    .pace-bar-labels { display: flex; justify-content: space-between;
                       font-size: 10px; color: var(--text-muted); margin-bottom: 5px; }
    .pace-track  { position: relative; height: 6px; background: var(--border);
                   border-radius: 3px; overflow: visible; }
    .pace-fill   { height: 100%; border-radius: 3px; transition: width .6s ease; }
    .pace-marker { position: absolute; top: -4px; width: 2px; height: 14px;
                   background: var(--text-secondary); border-radius: 1px; transform: translateX(-50%); }
    @media (max-width: 600px) {
      .pace-card  { padding: 14px 0; }
      .pace-header{ padding: 0 14px 4px; }
      .pace-grid  { grid-template-columns: repeat(2, 1fr); }
      .pace-stat:nth-child(3n)  { border-right: 1px solid var(--border); }
      .pace-stat:nth-child(2n)  { border-right: none; }
      .pace-stat:nth-last-child(-n+3) { border-bottom: 1px solid var(--border); }
      .pace-stat:nth-last-child(-n+2) { border-bottom: none; }
      .pace-stat  { padding: 10px 14px; }
      .pace-bar-wrap { padding: 4px 14px 0; }
      .pace-bar-labels { padding: 0; }
    }

    /* Alert */
    .alert-bar { display: flex; align-items: center; gap: 10px; background: var(--amber-soft);
      border: 1px solid #fde68a; border-radius: var(--radius); padding: 10px 14px;
      font-size: 13px; color: #92400e; margin-bottom: 14px; }

    /* Cards */
    .card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
            padding: 18px 20px; box-shadow: var(--shadow); min-width: 0; }
    .card-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 14px; }
    .card-title { font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
    .card-subtitle { font-size: 11.5px; color: var(--text-muted); margin-top: 2px; }
    .source-chip { display: inline-flex; align-items: center; gap: 5px; font-size: 11px;
      color: var(--text-muted); border: 1px solid var(--border); border-radius: 20px; padding: 2px 8px; flex-shrink: 0; }
    .source-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green);
                  animation: pulse 2s infinite; }
    @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.4} }

    /* Chart grids */
    .grid-2-1 { display: grid; grid-template-columns: 2fr 1fr; gap: 10px; min-width: 0; }
    .grid-1-1 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; min-width: 0; }
    .grid-4-1 { display: grid; grid-template-columns: 4fr 1fr; gap: 10px; align-items: stretch; min-width: 0; }
    /* Itens de grid herdam min-width:auto por padrão (como flex) — sem isso,
       conteúdo largo (tabela, árvore de diagnóstico) força a coluna a não
       encolher no mobile e vaza pra direita da tela, mesmo com a grid
       colapsando pra 1 coluna. */
    .grid-2-1 > *, .grid-1-1 > *, .grid-4-1 > * { min-width: 0; overflow-x: hidden; }
    @media (max-width: 900px) { .grid-2-1, .grid-1-1, .grid-4-1 { grid-template-columns: 1fr; } }

    /* Lost Impression Share — árvore de diagnóstico */
    .lost-is-tree { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 6px 0 2px; }
    .lit-row { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; width: 100%; }
    .lit-box { border: 1px solid var(--border); border-radius: 8px; padding: 8px 12px; text-align: center;
               background: var(--bg); min-width: 96px; flex: 1 1 0; }
    @media (max-width: 600px) {
      /* Empilha as 2 linhas x 2 colunas em 1 coluna única no mobile;
         altura/largura equalizadas via equalizeCardHeights('#lostIsTree', '.lit-box'). */
      .lit-row { flex-direction: column; }
      .lit-box { flex: none; }
    }
    .lit-box .lit-pct { font-size: 17px; font-weight: 700; line-height: 1.1; }
    .lit-box .lit-label { font-size: 10.5px; color: var(--text-secondary); margin-top: 2px; }
    .lit-box.lit-is    { border-color: var(--green); background: var(--green-soft); }
    .lit-box.lit-is    .lit-pct { color: var(--green); }
    .lit-box.lit-lost  { border-color: var(--red); background: var(--red-soft); }
    .lit-box.lit-lost  .lit-pct { color: var(--red); }
    .lit-box.lit-budget .lit-pct { color: var(--red); }
    .lit-box.lit-rank   { border-color: var(--accent); }
    .lit-box.lit-rank   .lit-pct { color: var(--accent); }
    .lit-connector { width: 1px; height: 10px; background: var(--border); }
    .lit-delta { font-size: 10px; font-weight: 600; margin-top: 3px; display: block; }
    .lit-delta.pos { color: var(--green); }
    .lit-delta.neg { color: var(--red); }
    .lit-delta.neu { color: var(--text-muted); }

    .lost-is-opp { display: flex; align-items: center; gap: 10px; background: var(--red-soft);
      border: 1px solid #fecaca; border-radius: var(--radius); padding: 10px 14px;
      font-size: 13px; color: #991b1b; margin-bottom: 14px; }
    /* .lost-is-opp-text = item flex com o texto: sem min-width:0 o item de flex
       não encolhe abaixo da largura da frase inteira sem quebra, vazando pra
       direita da tela no mobile (mesmo bug de grid, mas em flex). */
    .lost-is-opp-emoji { flex-shrink: 0; }
    .lost-is-opp-text { min-width: 0; flex: 1; }
    [data-theme="dark"] .lost-is-opp { color: #fca5a5; border-color: #7f1d1d; }
    @media (max-width: 900px) {
      /* Donut charts: troca flex:1 por altura fixa para Chart.js calcular corretamente */
      #convChart, #upsellPieChart { display: block; width: 100% !important; }
      #convChart { height: 260px !important; }
      #upsellPieChart { height: 240px !important; }
    }

    /* Gauges */
    .gauge-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
    @media (max-width: 1000px) { .gauge-row { grid-template-columns: repeat(2, 1fr); } }
    @media (max-width: 500px)  { .gauge-row { grid-template-columns: 1fr; } }
    .gauge-card { background: var(--surface); border: 1px solid var(--border);
      border-radius: var(--radius); padding: 14px 16px; box-shadow: var(--shadow); }
    .gauge-lbl { font-size: 11.5px; color: var(--text-secondary); font-weight: 500; margin-bottom: 8px; }
    .gauge-row2 { display: flex; align-items: center; gap: 8px; }
    .gauge-track { flex: 1; height: 7px; background: var(--border); border-radius: 4px; overflow: hidden; }
    .gauge-fill { height: 100%; border-radius: 4px; transition: width .6s; }
    .gauge-num { font-size: 13px; font-weight: 700; min-width: 46px; text-align: right; }
    .gauge-sub { font-size: 11px; color: var(--text-muted); margin-top: 4px; }

    /* Table */
    .table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; position: relative; max-width: 100%; }
    table { width: 100%; min-width: 480px; border-collapse: collapse; font-size: 12.5px; }
    /* Scroll hint: fade + indicator bar visible on mobile */
    @media (max-width: 700px) {
      .table-wrap-scroll { scrollbar-width: thin; scrollbar-color: var(--accent) var(--border); }
      .table-wrap-scroll::-webkit-scrollbar { height: 4px; }
      .table-wrap-scroll::-webkit-scrollbar-track { background: var(--border); border-radius: 2px; }
      .table-wrap-scroll::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 2px; }
      /* Right-fade gradient indicating more content */
      .table-wrap-scroll::after {
        content: ''; pointer-events: none;
        position: absolute; top: 0; right: 0; width: 32px; height: 100%;
        background: linear-gradient(to left, var(--surface) 0%, transparent 100%);
      }
    }
    thead tr { border-bottom: 2px solid var(--border); }
    th { text-align: left; font-size: 10.5px; font-weight: 600; text-transform: uppercase;
         letter-spacing: .06em; color: var(--text-muted); padding: 0 10px 10px; }
    th:first-child { padding-left: 4px; }
    tbody tr { border-bottom: 1px solid var(--border); transition: background .1s; }
    tbody tr:last-child { border-bottom: none; }
    tbody tr:hover { background: var(--bg); }
    td { padding: 11px 10px; vertical-align: middle; }
    td:first-child { padding-left: 4px; }
    td.num { text-align: right; font-variant-numeric: tabular-nums; }
    .tr-total { border-top: 2px solid var(--border) !important; border-bottom: none !important; background: #f8fafc; font-weight: 700; }
    .tr-total:hover { background: #f1f5f9 !important; }
    th.num { text-align: right; }
    .cname { display: flex; align-items: center; font-weight: 500; }
    .dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 8px; }
    .bar-cell { display: flex; align-items: center; gap: 7px; }
    .bar-track { flex: 1; height: 5px; background: var(--border); border-radius: 3px; overflow: hidden; }
    .bar-fill { height: 100%; border-radius: 3px; }
    footer { text-align: center; padding: 32px; font-size: 11.5px; color: var(--text-muted); }

    /* Conversion Funnel */
    .funnel-wrap { display: flex; flex-direction: column; gap: 0; }
    .funnel-row { display: flex; align-items: center; gap: 10px; padding: 4px 0; }
    .funnel-lbl { min-width: 82px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
                  text-align: right; flex-shrink: 0; }
    .funnel-bar-col { flex: 1; min-width: 0; }
    .funnel-bar { height: 36px; border-radius: 6px; display: flex; align-items: center;
                  padding: 0 14px; min-width: 48px; transition: width .55s ease; }
    .funnel-bar-val { color: white; font-size: 12.5px; font-weight: 700; white-space: nowrap; }
    .funnel-stats { min-width: 130px; flex-shrink: 0; padding-left: 8px; }
    .funnel-count { font-size: 13px; font-weight: 700; color: var(--text-primary); }
    .funnel-pct   { font-size: 11px; color: var(--text-muted); margin-top: 2px; }
    .funnel-connector { display: flex; align-items: center; gap: 0; padding: 2px 0 2px 92px; }
    .funnel-arrow-col { width: 36px; display: flex; flex-direction: column; align-items: center; }
    .funnel-v-line { width: 2px; height: 14px; background: var(--border); }
    .funnel-rate-txt { font-size: 11px; font-weight: 600; padding-left: 8px;
                       color: var(--text-secondary); white-space: nowrap; }
    @media (max-width: 600px) {
      .funnel-lbl { min-width: 68px; font-size: 11px; }
      .funnel-stats { min-width: 90px; }
      .funnel-count { font-size: 12px; }
      .funnel-bar { height: 30px; }
      .card { padding: 14px 12px; }
      .card-header { margin-bottom: 10px; }
      table { min-width: 360px; font-size: 11.5px; }
      th, td { padding: 7px 6px; }
    }

    /* ── Por Produto — Teste Pacote Completo R$79,90 ─────────────────────── */
    /* Subgrid: as 5 linhas internas (header / régua / métricas / atribuição /
       gráfico) são COMPARTILHADAS entre os dois cards — métricas e gráficos
       ficam alinhados horizontalmente na mesma altura nos dois boxes.
       Fallback sem subgrid: cada card alinha sozinho (grid normal), sem quebrar. */
    .produto-grid { display:grid; grid-template-columns:1fr 1fr; grid-template-rows:repeat(5,auto); gap:12px; }
    @media(max-width:900px){ .produto-grid { grid-template-columns:1fr; } }
    .produto-card { background:var(--surface); border:1px solid var(--border); border-radius:var(--radius);
      padding:16px 20px; box-shadow:var(--shadow); transition:box-shadow .15s;
      display:grid; grid-template-rows:subgrid; grid-row:span 5; align-content:start; }
    .produto-card > .produto-card-top { grid-row:1; }
    .produto-card > .cac-regua-wrap   { grid-row:2; }
    .produto-card > .produto-metrics  { grid-row:3; }
    .produto-card > .produto-attrib   { grid-row:4; }
    .produto-card > .produto-chart    { grid-row:5; }
    .produto-card:hover { box-shadow:var(--shadow-md); }
    .produto-card.teste { border-color:#c7d2fe; }
    [data-theme="dark"] .produto-card.teste { border-color:#4338ca; }
    .produto-card-top { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-bottom:10px; }
    .produto-card-label { font-size:11px; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:var(--text-muted); margin-bottom:3px; }
    .produto-card-value { font-size:26px; font-weight:700; color:var(--text-primary); letter-spacing:-.5px; }
    .produto-card-value.ok    { color:var(--green); }
    .produto-card-value.warn  { color:var(--amber); }
    .produto-card-value.bad   { color:var(--red); }
    .produto-card-valuesub { font-size:10.5px; color:var(--text-muted); margin-top:3px; }
    .produto-card-topright { display:flex; flex-direction:column; align-items:flex-end; gap:6px; }
    .produto-badge { font-size:11px; font-weight:600; padding:3px 10px; border-radius:20px;
      background:#e0e7ff; color:#4338ca; white-space:nowrap; }
    [data-theme="dark"] .produto-badge { background:#312e81; color:#c7d2fe; }
    .produto-badge.ok   { background:#dcfce7; color:#15803d; }
    .produto-badge.warn { background:#fef9c3; color:#a16207; }
    .produto-badge.bad  { background:#fee2e2; color:#b91c1c; }
    [data-theme="dark"] .produto-badge.ok   { background:rgba(22,163,74,.2);  color:#4ade80; }
    [data-theme="dark"] .produto-badge.warn { background:rgba(217,119,6,.2);  color:#fbbf24; }
    [data-theme="dark"] .produto-badge.bad  { background:rgba(220,38,38,.2);  color:#f87171; }
    .produto-meta { font-size:10.5px; color:var(--text-muted); text-align:right; }
    .produto-chip { display:inline-flex; align-items:center; font-size:10px; font-weight:700; letter-spacing:.04em;
      border-radius:4px; padding:2px 7px; margin-left:8px; vertical-align:middle; text-transform:none; }
    .produto-chip.demo { background:var(--amber-soft); color:var(--amber); border:1px dashed var(--amber); }
    .produto-metrics { margin-top:12px; }
    /* Texto corrido (SEM flex: flexbox quebrava "100%" e "das vendas" em itens
       separados, engolindo o espaço entre eles e forçando quebra de linha) */
    .produto-attrib { font-size:11px; color:var(--text-secondary); margin-top:10px; line-height:1.5; }
    .produto-attrib .warn { color:var(--amber); font-weight:600; }
    .produto-chart { height:150px; margin-top:14px; position:relative; }
    /* Chip 🧪 da campanha do teste na tabela Campanhas */
    .camp-teste-chip { font-size:9.5px; font-weight:700; letter-spacing:.02em; white-space:nowrap;
      background:#ccfbf1; color:#0f766e; border-radius:4px; padding:1px 5px; margin-left:6px; }
    [data-theme="dark"] .camp-teste-chip { background:rgba(13,148,136,.22); color:#5eead4; }

    /* Régua de CAC (benchmark do teste) */
    .cac-regua-wrap { margin-top:8px; padding-top:16px; }
    .cac-regua { position:relative; height:20px; }
    .cac-regua-zonas { display:flex; height:100%; border-radius:6px; overflow:hidden; }
    .cac-regua-zonas span { height:100%; }
    .cac-regua-marker { position:absolute; top:-5px; bottom:-5px; width:2px; border-radius:2px;
      background:var(--text-primary); transform:translateX(-1px); }
    .cac-regua-marker::after { content:attr(data-val); position:absolute; top:-15px; left:50%;
      transform:translateX(-50%); font-size:10px; font-weight:700; white-space:nowrap; color:var(--text-primary); }
    .cac-regua-ticks { position:relative; height:15px; margin-top:3px; font-size:9.5px; color:var(--text-muted); }
    .cac-regua-ticks span { position:absolute; transform:translateX(-50%); white-space:nowrap; }
    .cac-regua-caption { text-align:right; font-size:9px; letter-spacing:.02em;
      color:var(--text-muted); opacity:.85; margin-top:1px; }

    /* ── Dark Mode ────────────────────────────────────────────────────────── */
    [data-theme="dark"] {
      --bg:#0f172a; --surface:#1e293b; --border:#334155;
      --text-primary:#f1f5f9; --text-secondary:#94a3b8; --text-muted:#64748b;
      --green-soft:rgba(22,163,74,.18); --red-soft:rgba(220,38,38,.18);
      --amber-soft:rgba(217,119,6,.18);
      --shadow:0 1px 3px rgba(0,0,0,.4),0 1px 2px rgba(0,0,0,.3);
      --shadow-md:0 4px 16px rgba(0,0,0,.55);
    }
    [data-theme="dark"] .filter-select { color-scheme:dark; }
    [data-theme="dark"] input[type="date"] { color-scheme:dark; }
    [data-theme="dark"] .tr-total { background:#1a2942 !important; }
    [data-theme="dark"] .tr-total:hover { background:#1d2f4a !important; }
    .theme-btn { background:none; border:none; padding:4px; cursor:pointer; font-size:15px; line-height:1;
      color:var(--text-muted); transition:color .15s; flex-shrink:0; }
    .theme-btn:hover { color:var(--accent); }

    /* ── Skeleton Loading ─────────────────────────────────────────────────── */
    @keyframes shimmer { 0%{background-position:200% 0} 100%{background-position:-200% 0} }
    .skeleton { background:linear-gradient(90deg,var(--border) 25%,var(--bg) 50%,var(--border) 75%);
      background-size:200% 100%; animation:shimmer 1.4s infinite; border-radius:4px; }
    .kpi-skel-lbl  { height:11px; width:60%; margin-bottom:10px; }
    .kpi-skel-val  { height:22px; width:72%; margin-bottom:12px; }
    .kpi-skel-spark{ height:34px; width:100%; margin-bottom:8px; }
    .kpi-skel-sub  { height:10px; width:80%; }

    /* ── Tooltip ──────────────────────────────────────────────────────────────
       .has-tip = card com o atributo data-tip; .tip-icon = botão "i" no canto
       superior direito (tap-friendly no mobile, já que :hover não existe lá).
       Abre no hover (desktop) OU no toque (classe .tip-open via JS, ver
       toggleTipIcons() mais abaixo). */
    .has-tip { position:relative; }
    .tip-icon { position:absolute; top:8px; right:8px; width:20px; height:20px;
      display:flex; align-items:center; justify-content:center; border-radius:50%;
      background:var(--bg); border:1px solid var(--border); color:var(--text-muted);
      font-size:10.5px; font-weight:700; font-style:italic; font-family:Georgia,serif;
      cursor:help; z-index:6; line-height:1; }
    .tip-icon:hover, .tip-icon.tip-open { border-color:var(--accent); color:var(--accent); }
    .has-tip::after {
      content:attr(data-tip);
      position:absolute; top:32px; right:4px; left:auto; bottom:auto;
      background:#1e293b; color:#f1f5f9; font-size:11px; line-height:1.45;
      padding:8px 11px; border-radius:8px; white-space:pre-wrap;
      min-width:180px; max-width:260px; text-align:left;
      opacity:0; pointer-events:none; transition:opacity .15s; z-index:9999;
      box-shadow:0 4px 12px rgba(0,0,0,.25);
    }
    .has-tip:hover::after,
    .has-tip.tip-open::after { opacity:1; }
    @media (max-width: 600px) {
      .tip-icon { width:22px; height:22px; font-size:12px; top:6px; right:6px; }
      .has-tip::after { font-size:12px; padding:9px 12px; line-height:1.5;
        min-width:190px; max-width:min(270px, 78vw); }
    }

    /* ── Sortable Table Headers ───────────────────────────────────────────── */
    th.sortable { cursor:pointer; user-select:none; white-space:nowrap; }
    th.sortable:hover { color:var(--accent); }
    th.sort-asc::after  { content:' ↑'; color:var(--accent); }
    th.sort-desc::after { content:' ↓'; color:var(--accent); }

    /* ── KPI Target Progress Bar ──────────────────────────────────────────── */
    .kpi-tgt { height:3px; border-radius:2px; margin-top:5px; background:var(--border); overflow:hidden; }
    .kpi-tgt-fill { height:100%; border-radius:2px; transition:width .6s ease; }

    /* ── Estornos grid ───────────────────────────────────────────────────── */
    .refund-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; }
    @media (max-width: 700px) { .refund-grid { grid-template-columns:1fr; } }

    /* ── Upsell type table — mobile sem scroll horizontal ────────────────── */
    .trend-in-receita { display:none; }
    @media (max-width: 700px) {
      .tendencia-col { display:none; }
      .trend-in-receita { display:inline; font-size:13px; font-weight:700; }
      #upsellTypeTable { min-width:0; font-size:11.5px; }
      #upsellTypeTable th, #upsellTypeTable td { padding:7px 5px; }
    }

    /* ── Keyboard shortcut hint ───────────────────────────────────────────── */
    .kbd-hint { display:inline-block; background:var(--border); border-radius:3px;
      font-size:10px; font-weight:700; padding:1px 4px; color:var(--text-muted);
      letter-spacing:0; font-family:monospace; }


    /* ── Sidebar (navegação principal — Visão Geral / Campanhas / Upsell + módulos satélite) ── */
    .app-shell { display: flex; align-items: stretch; min-height: 100vh; }
    .app-content { flex: 1; min-width: 0; display: block; }

    .sidebar { width: 216px; flex-shrink: 0; background: var(--surface); border-right: 1px solid var(--border);
               display: flex; flex-direction: column; padding: 14px 10px; position: sticky; top: 0;
               height: 100vh; overflow-y: auto; transition: width .15s ease; z-index: 90; }
    .sidebar-top { display: flex; align-items: center; justify-content: space-between; padding: 2px 4px 16px; }
    .sidebar-brand { display: flex; align-items: center; gap: 8px; min-width: 0; }
    .sidebar-brand-label { font-size: 13px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sidebar-collapse-btn { background: none; border: 1px solid var(--border); border-radius: 6px; width: 22px; height: 22px;
      display: flex; align-items: center; justify-content: center; color: var(--text-secondary); cursor: pointer; flex-shrink: 0; }
    .sidebar-collapse-btn:hover { border-color: var(--accent); color: var(--accent); }
    .sidebar-collapse-btn svg { transition: transform .15s ease; }

    .sidebar-nav { display: flex; flex-direction: column; gap: 2px; }
    .sidebar-nav-item { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px;
      border: none; background: none; color: var(--text-secondary); font-size: 13px; font-weight: 500;
      cursor: pointer; text-align: left; text-decoration: none; width: 100%; }
    .sidebar-nav-item:hover { background: var(--bg); color: var(--text-primary); }
    .sidebar-nav-item.active { background: var(--text-primary); color: #fff; font-weight: 600; }
    .sidebar-nav-icon { width: 16px; height: 16px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; }
    .sidebar-nav-label { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sidebar-divider { height: 1px; background: var(--border); margin: 10px 4px; }

    .view.is-hidden { display: none; }

    /* Google Ads CAC / Tracking Gateway embutidos via iframe (páginas próprias,
       não fundidas — ver comentário no HTML). Essas páginas têm breakpoints
       próprios (900-1100px) pensados pra ocupar a janela inteira quando abertas
       sozinhas. Dentro do dashboard elas perdem ~216px pra sidebar + o padding
       do main — em telas de notebook isso é o suficiente pra cair no layout
       "compacto" delas mesmo com a janela em modo desktop. Solução: no desktop
       (>600px) a view "come" o padding lateral do main (margem negativa) e o
       iframe recebe min-width — se ainda faltar espaço, aparece scroll
       horizontal em vez de forçar o layout compacto delas. No mobile real
       (<=600px) não mexemos: a página embutida já tem seu próprio layout
       mobile e a largura disponível já é a largura real da tela. */
    /* Sem borda/sombra/cantos — deixa o iframe se misturar com o resto da
       página (mesmo --bg dos dois lados) em vez de parecer um "cartão"
       flutuante. A margem negativa recupera o padding lateral do main de
       verdade (sem padding compensando de volta), reduzindo o respiro nas
       laterais do conteúdo embutido. */
    .embed-frame { display: block; width: 100%; border: none; border-radius: 0;
