// ── DO NOT register ChartDataLabels globally — enable per chart ──────────────

// ─── CONFIG ──────────────────────────────────────────────────────────────────
const TICKET        = 16.86;  // ticket médio real abril/26 (receita ÷ pedidos reais do banco)
// ⚠ TARGET_* / MONTHLY_*_TARGET abaixo são apenas FALLBACK: a fonte real das
// metas é a tabela monthly_targets no Supabase (módulo "Metas" na sidebar).
// Só valem se a tabela estiver vazia ou inacessível — ver targetFor().
const TARGET_CPA    =  9.00;  // fallback — meta CAC
const TARGET_UPSELL = 32;     // fallback — % meta upsell
const CAMP_COLORS   = { RISCO_DOC:'#2563eb', ADDONS:'#7c3aed', RENAVAM:'#0891b2', ROUBO_FURTO:'#d97706', MULTAS:'#dc2626' };
const BASE_CAMPS    = [
  { name:'RISCO_DOC',   convShare:.294, costShare:.266 },
  { name:'ADDONS',      convShare:.235, costShare:.223 },
  { name:'RENAVAM',     convShare:.224, costShare:.244 },
  { name:'ROUBO_FURTO', convShare:.163, costShare:.158 },
  { name:'MULTAS',      convShare:.087, costShare:.122 },
];
// Referência: abril/2026 — receita R$82.286 | ads ~R$44.953 | bureau ~R$19.090 | lucro líq. ~R$15.116
// conv = pedidos reais do banco (44.953 ÷ 9,21 = 4.881) | ticket real = 82.286 ÷ 4.881 = R$16,86
const MONTHLY = { revenue:82286, cost:44953, conv:4881, profit:18243, roas:1.83, convRate:4.04 };
const MONTHLY_BUDGET              = 89000;  // fallback — R$ orçamento Google Ads
const MONTHLY_REVENUE_TARGET      = 163000; // fallback — R$ meta receita
const MONTHLY_PROFIT_TARGET       = 36000;  // fallback — R$ meta lucro bruto
const MONTHLY_NET_PROFIT_TARGET   = 30000;  // fallback — R$ meta lucro líquido
const TAX_PCT_DEFAULT             = 8;      // fallback — % imposto sobre a receita (todos os meses)

// ─── TESTE PACOTE COMPLETO R$79,90 ───────────────────────────────────────────
// Benchmark 15/07/2026 (30d reais Supabase/Pagar.me): m1 funil atual R$19,60,
// CAC real R$17,40, lucro R$2,20/comprador. Régua do teste com bureau REAL
// (R$25,53/venda — confirmado 16/07, plano "Pacote Completo + Leilão", 100%
//  CheckTudo, 8 consultas: relatório base 0,18 + base nacional 1,03 + base
//  nac. unificada 3,04 + base estadual/dono 1,35 + roubo e furto 1,49 +
//  gravame 1,24 + indício de sinistro 2,10 + leilão completo 15,10):
//   m2 = 79,90×0,962 − 25,53 = R$51,33 → break-even ~51
//   empate = m2×CAC1/m1 = 51,33×17,40/19,60 ≈ R$46 → meta (vitória) = 40–46
const PRODUTO_TESTE = {
  preco:          79.90,
  campMatch:      'PACOTAO',     // casa "[SEARCH] [COMPRA] [LP-PACOTAO-1] [BEST] - JUL-2026" (substring, uppercase); utm da LP também precisa conter "pacotao"
  inicio:         '2026-07-16',  // primeiro dia do teste (campanha criada 16/07)
  bureauPorVenda: 25.53,         // custo REAL/venda (16/07): 8 consultas 100% CheckTudo, leilão 15,10 é o maior item
  cacMetaMin: 40, cacMetaMax: 46, cacEmpate: 46, cacBreakEven: 51,
  reguaMax:   90,                // fim da escala visual da régua
  learningConv: 30,              // nº aproximado de conversões p/ sair do learning (conferir doc do Google)
};
let TESTE_DAILY = [];  // {dateStr, vendas, receita, custoAds, vendasUtm} — série real das views SQL
let TESTE_DEMO  = false; // true = painel exibindo dados demo (chip amarelo visível)
let TESTE_WIRED = false; // true = fetch das views do teste OK (mesmo com 0 linhas ≠ demo)

// Registra a campanha do teste no universo de campanhas: campTotals() agrega por
// substring do nome (qualquer campanha do Ads contendo campMatch cai nesta linha),
// com flag teste=true — a tabela Campanhas usa a régua do teste (meta/empate/BE) no CAC
// dela, não a meta CAC do funil base (~R$9), e mostra o chip 🧪.
// shares 0 = fora do rateio do fallback demo (filtrado em campTotals()).
BASE_CAMPS.push({ name: PRODUTO_TESTE.campMatch, convShare: 0, costShare: 0, teste: true });
CAMP_COLORS[PRODUTO_TESTE.campMatch] = '#0d9488'; // teal — distinto das 5 cores atuais

// ─── METAS (monthly_targets) ─────────────────────────────────────────────────
// Fonte real das metas: tabela monthly_targets (Supabase principal), editável
// no módulo "Metas" da sidebar. Fallback em cascata: linha do mês da data →
// linha mais recente ANTERIOR (meta vale até ser alterada) → constantes acima
// (dash nunca quebra, mesmo com a tabela vazia ou o Supabase fora).
let MONTHLY_TARGETS = []; // linhas de monthly_targets, ordenadas por month asc

function targetFor(dateStr) {
  const mo = String(dateStr || '').slice(0, 7) + '-01';
  const num = v => { const n = parseFloat(v); return isFinite(n) ? n : null; };
  // Herança POR CAMPO: vale o valor não-nulo mais recente <= mês pedido.
  // Campo deixado vazio num mês herda o do mês anterior (como o form promete);
  // se nenhum mês tiver valor, cai na constante fallback.
  const pick = (field, fb) => {
    for (let i = MONTHLY_TARGETS.length - 1; i >= 0; i--) {
      const r = MONTHLY_TARGETS[i];
      if (String(r.month).slice(0, 10) <= mo) {
        const v = num(r[field]);
        if (v !== null) return v;
      }
    }
    return fb;
  };
  return {
    cpa:       pick('target_cpa',        TARGET_CPA),
    upsell:    pick('target_upsell_pct', TARGET_UPSELL),
    budget:    pick('monthly_budget',    MONTHLY_BUDGET),
    revenue:   pick('revenue_target',    MONTHLY_REVENUE_TARGET),
    profit:    pick('profit_target',     MONTHLY_PROFIT_TARGET),
    netProfit: pick('net_profit_target', MONTHLY_NET_PROFIT_TARGET),
    taxPct:    pick('tax_pct',           TAX_PCT_DEFAULT),
  };
}

// Meta "ativa" para números agregados do período filtrado (projeções, barras
// de meta, badges): usa o mês do ÚLTIMO dia do filtro (mês corrente do filtro).
// Linhas por-dia dos gráficos usam targetFor(dia) diretamente.
function activeTargets() {
  let ds = null;
  if (typeof filtered !== 'undefined' && filtered && filtered.length) {
    ds = filtered[filtered.length - 1].dateStr;
  } else {
    const n = new Date(), p = x => String(x).padStart(2, '0');
    ds = `${n.getFullYear()}-${p(n.getMonth() + 1)}-${p(n.getDate())}`;
  }
  return targetFor(ds);
}

// ─── SUPABASE ─────────────────────────────────────────────────────────────────
const SUPA_URL = 'https://ftmgmfdqdqxboiktxcoj.supabase.co';
const SUPA_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZ0bWdtZmRxZHF4Ym9pa3R4Y29qIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzc0MTIwNzAsImV4cCI6MjA5Mjk4ODA3MH0.IfOKtwpBB9orGN3UnCZDG8RYEHTAEAsX0LHxV3WBfCs';
const SUPA_HDR = { apikey: SUPA_KEY, Authorization: 'Bearer ' + SUPA_KEY };

// Supabase do SITE (checkouts) — projeto separado; alimenta a Taxa de Conversão
const SITE_SUPA_URL = 'https://ozquoloetuzynnyzkado.supabase.co';
const SITE_SUPA_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im96cXVvbG9ldHV6eW5ueXprYWRvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NTg4MjU1NzcsImV4cCI6MjA3NDQwMTU3N30.w4acA-baHGvo0k8VOKjOYhfdvbTNOvT8E3Kov-VeJQk';
const SITE_SUPA_HDR = { apikey: SITE_SUPA_KEY, Authorization: 'Bearer ' + SITE_SUPA_KEY };

const ADDON_LABELS = {
  'bin_estadual':             'BIN Estadual',
  'bin_estadual_owner':       'Proprietário Estadual',
  'bin_federal':              'BIN Federal',
  'gravame':                  'Gravame',
  'historico_leilao':         'Histórico Leilão',
  'indicio_sinistro':         'Indício Sinistro',
  'dados_proprietario_atual': 'Dados do Proprietário',
  'renavam':                  'RENAVAM',
};
function addonLabel(key) {
  if (!key) return key;
  if (ADDON_LABELS[key]) return ADDON_LABELS[key];
  // Combos: "combo:k1+k2+..." → junta labels dos componentes
  if (key.startsWith('combo:')) {
    return key.slice(6).split('+').map(k => ADDON_LABELS[k] || k).join(' + ');
  }
  return key;
}

// PostgREST limita respostas a 1000 linhas por request e sinaliza truncamento
// só com HTTP 206 (que fetch trata como "ok"). Paginamos via header Range até
// receber uma página menor que SUPA_PAGE_SIZE (sinal de última página).
// Chamadas com &limit=N (N < 1000) continuam funcionando: a primeira página
// já vem menor que o PAGE_SIZE e o loop encerra.
const SUPA_PAGE_SIZE = 1000;

async function supaGet(path, _attempt = 1, base = SUPA_URL, hdr = SUPA_HDR) {
  try {
    let allRows = [];
    let offset = 0;
    while (true) {
      const r = await fetch(base + path, {
        headers: { ...hdr, Range: `${offset}-${offset + SUPA_PAGE_SIZE - 1}` },
      });
      if (!r.ok) throw new Error('Supabase ' + r.status + ': ' + path);
      const page = await r.json();
      allRows = allRows.concat(page);
      if (page.length < SUPA_PAGE_SIZE) break; // última página (incompleta ou vazia)
      offset += SUPA_PAGE_SIZE;
    }
    return allRows;
  } catch (err) {
    // Retry: primeiro load pode pegar o Supabase "frio" (projeto pausado/acordando)
    // ou um 500 transiente de infra — mais tentativas/backoff (era 3 / até 2.4s,
    // subiu pra 5 / até 8s) pra dar mais chance de estabilizar antes do fallback demo.
    if (_attempt < 5) {
      await new Promise(res => setTimeout(res, 800 * _attempt));
      return supaGet(path, _attempt + 1, base, hdr);
    }
    throw err;
  }
}

async function loadSupabaseData() {
  const pad   = n => String(n).padStart(2, '0');
  const now   = new Date();
  const today = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
  const start = '2026-01-01';
  const qs    = `date=gte.${start}&date=lte.${today}`;

  const gadsQs = `date=gte.${start}&date=lte.${today}`;
  const [revRows, upsRows, ubtRows, burRows, gadsRows, refRows, balRows, burTypeRows, chkRows, tgtRows, compRows, utmRows] = await Promise.all([
    supaGet(`/rest/v1/revenue_daily?${qs}&select=date,revenue,paid_orders`),
    supaGet(`/rest/v1/upsell_daily?${qs}&select=date,upsell_orders,upsell_rate`),
    supaGet(`/rest/v1/upsell_by_type?${qs}&select=date,addon_key,qty,revenue`),
    supaGet(`/rest/v1/bureau_daily?${qs}&select=date,custo_bureau,lucro_bruto,margem_pct`),
    supaGet(`/rest/v1/google_ads_campaign_daily?${gadsQs}&select=date,campaign_id,campaign_name,cost_micros,conversions,impressions,search_impression_share,search_budget_lost_is,search_rank_lost_is&order=date.asc`),
    supaGet(`/rest/v1/refunds_daily?${qs}&select=date,refund_count,refund_value`),
    supaGet(`/rest/v1/ads_balance_history?select=checked_at,balance_brl,alert_level&order=checked_at.desc&limit=30`).catch(() => []),
    supaGet(`/rest/v1/bureau_by_type_daily?${qs}&select=date,bureau,vendido_real,custo_bureau`).catch(() => []),
    // Checkouts reais — Supabase do SITE; nunca quebra a dash se o projeto estiver fora
    supaGet(`/rest/v1/checkouts_daily?${qs}&select=date,checkouts_started`, 1, SITE_SUPA_URL, SITE_SUPA_HDR).catch(() => []),
    // Metas mensais — tabela pequena, sem paginação necessária; nunca quebra a dash
    supaGet(`/rest/v1/monthly_targets?select=*&order=month.asc`).catch(() => []),
    // Teste Pacote Completo R$79,90 — vendas do produto (migration 014, Supabase da dash).
    // null = view ausente/fetch falhou → painel cai no modo demo; [] = view ok sem vendas.
    supaGet(`/rest/v1/revenue_daily_completa?${qs}&select=date,vendas,receita`).catch(() => null),
    // Cross-check de atribuição — checkouts pagos por utm×plano (Supabase do SITE)
    supaGet(`/rest/v1/checkouts_campaign_daily?${qs}&select=date,utm_campaign,paid_count`, 1, SITE_SUPA_URL, SITE_SUPA_HDR).catch(() => null),
  ]);
  ADS_BALANCE_DATA = balRows || [];
  BUREAU_TYPE_ROWS = burTypeRows || [];
  MONTHLY_TARGETS  = (tgtRows || []).slice().sort((a, b) => String(a.month).localeCompare(String(b.month)));

  const upsMap = new Map();
  for (const u of upsRows) upsMap.set(String(u.date).slice(0,10), u);

  const burMap = new Map();
  for (const b of burRows) burMap.set(String(b.date).slice(0,10), b);

  const refMap = new Map();
  for (const r of refRows) refMap.set(String(r.date).slice(0,10), r);

  const chkMap = new Map();
  for (const c of chkRows) chkMap.set(String(c.date).slice(0,10), parseInt(c.checkouts_started) || 0);

  ALL_DAYS = revRows.map(row => {
    const dateStr = String(row.date).slice(0,10);
    const u       = upsMap.get(dateStr) || {};
    const b       = burMap.get(dateStr) || {};
    const ref     = refMap.get(dateStr) || {};
    const revenue = parseFloat(row.revenue)   || 0;
    const conv    = parseInt(row.paid_orders) || 0;
    const costBureau = parseFloat(b.custo_bureau) || 0;
    return {
      date:          new Date(dateStr + 'T00:00:00'),
      dateStr,
      revenue,
      conv,
      pedidos:       conv,
      cost:          0,
      costBureau,
      costTotal:     costBureau,
      profit:        +(revenue - costBureau).toFixed(2),
      checkouts:     chkMap.get(dateStr) || 0,
      upsellRate:    parseFloat(u.upsell_rate)  || 0,
      pedidosUpsell: parseInt(u.upsell_orders)  || 0,
      cac: null, cpv: null,
      refundCount:  parseInt(ref.refund_count)   || 0,
      refundValue:  parseFloat(ref.refund_value) || 0,
    };
  }).sort((a,b) => a.dateStr.localeCompare(b.dateStr));

  // Dias com custo (Ads/bureau) mas sem linha em revenue_daily eram descartados,
  // inflando o lucro do período. Cria entradas zeradas para essas datas;
  // mergeCostIntoAllDays() preenche os custos em seguida.
  const _dayKeys   = new Set(ALL_DAYS.map(d => d.dateStr));
  const _costDates = new Set();
  for (const g of gadsRows) _costDates.add(String(g.date).slice(0,10));
  for (const b of burRows)  _costDates.add(String(b.date).slice(0,10));
  for (const k of chkMap.keys()) _costDates.add(k); // dias com checkout mas sem receita
  for (const dateStr of _costDates) {
    if (_dayKeys.has(dateStr)) continue;
    const b          = burMap.get(dateStr) || {};
    const costBureau = parseFloat(b.custo_bureau) || 0;
    ALL_DAYS.push({
      date:          new Date(dateStr + 'T00:00:00'),
      dateStr,
      revenue:       0,
      conv:          0,
      pedidos:       0,
      cost:          0,
      costBureau,
      costTotal:     costBureau,
      profit:        +(-costBureau).toFixed(2),
      checkouts:     chkMap.get(dateStr) || 0,
      upsellRate:    0,
      pedidosUpsell: 0,
      cac: null, cpv: null,
      refundCount:   0,
      refundValue:   0,
    });
  }
  ALL_DAYS.sort((a,b) => a.dateStr.localeCompare(b.dateStr));

  UPSELL_TYPE_DATA = ubtRows.map(r => ({
    dateStr:  String(r.date).slice(0,10),
    addonKey: r.addon_key,
    label:    addonLabel(r.addon_key),
    count:    parseInt(r.qty)      || 0,
    revenue:  parseFloat(r.revenue) || 0,
  }));

  // Popula CAMPAIGN_DAILY_DATA a partir do Supabase (substitui CSV)
  CAMPAIGN_DAILY_DATA = gadsRows.map(r => ({
    dateStr:     String(r.date).slice(0, 10),
    campaign:    String(r.campaign_name || '').toUpperCase(),
    campaignId:  String(r.campaign_id || ''),
    cost:        (parseInt(r.cost_micros) || 0) / 1_000_000,
    conversions: parseFloat(r.conversions) || 0,
    revenue:     0,
    // Lost Impression Share — só vem preenchido para campanhas Search (NULL nas demais)
    impressions: parseInt(r.impressions) || 0,
    searchIS:      r.search_impression_share != null ? parseFloat(r.search_impression_share) : null,
    budgetLostIS:  r.search_budget_lost_is    != null ? parseFloat(r.search_budget_lost_is)    : null,
    rankLostIS:    r.search_rank_lost_is      != null ? parseFloat(r.search_rank_lost_is)      : null,
  }));
  console.log('[Dashboard] Google Ads (Supabase):', CAMPAIGN_DAILY_DATA.length, 'linhas carregadas.');
  populateCampaignFilter();

  // ── Teste Pacote Completo R$79,90: monta a série diária real ──────────────
  // compRows === null → view revenue_daily_completa ainda não existe (ou fetch
  // falhou) → TESTE_WIRED fica false e o painel mostra o demo com chip amarelo.
  if (compRows !== null) {
    TESTE_WIRED = true;
    TESTE_DEMO  = false;
    // Custo/dia: soma das campanhas do Ads cujo nome contém campMatch.
    // De quebra coleta os campaign_ids delas — o utm_campaign real gravado nos
    // checkouts é o ID do ValueTrack {campaignid} (ex.: "{24029972565}"), não o
    // nome, então o cross-check casa por ID (e por nome, como fallback).
    const costMap  = new Map();
    const testeIds = new Set();
    for (const r of CAMPAIGN_DAILY_DATA) {
      if (!r.campaign.includes(PRODUTO_TESTE.campMatch)) continue; // campaign já é uppercase
      costMap.set(r.dateStr, (costMap.get(r.dateStr) || 0) + r.cost);
      if (r.campaignId) testeIds.add(r.campaignId);
    }
    // Cross-check: checkouts pagos/dia cujo utm_campaign é da campanha do teste
    // (ID numérico dentro do valor OU nome contendo campMatch)
    const utmMap = new Map();
    for (const r of (utmRows || [])) {
      const raw    = String(r.utm_campaign || '');
      const digits = raw.replace(/\D/g, '');
      const isTeste = (digits && testeIds.has(digits)) || raw.toUpperCase().includes(PRODUTO_TESTE.campMatch);
      if (!isTeste) continue;
      const ds = String(r.date).slice(0, 10);
      utmMap.set(ds, (utmMap.get(ds) || 0) + (parseInt(r.paid_count) || 0));
    }
    const map = new Map();
    for (const r of compRows) {
      const ds = String(r.date).slice(0, 10);
      map.set(ds, { dateStr: ds, vendas: parseInt(r.vendas) || 0,
                    receita: parseFloat(r.receita) || 0, custoAds: 0,
                    vendasUtm: utmMap.get(ds) || 0 });
    }
    // Dia com custo da campanha e 0 vendas também entra (queima de verba visível)
    for (const ds of costMap.keys()) {
      if (!map.has(ds)) map.set(ds, { dateStr: ds, vendas: 0, receita: 0, custoAds: 0, vendasUtm: 0 });
    }
    for (const d of map.values()) d.custoAds = costMap.get(d.dateStr) || 0;
    TESTE_DAILY = Array.from(map.values()).sort((a, b) => a.dateStr.localeCompare(b.dateStr));
    console.log('[Dashboard] Teste Pacote Completo:', TESTE_DAILY.length, 'dias reais carregados.');
  }

  mergeCostIntoAllDays();
}

// Acrescenta ao <select> de campanhas as que existem nos dados mas não estão nas
// options hardcoded (ex.: campanha do teste R$79,90, futuras campanhas novas).
// Sem isso, uma campanha nova apareceria na tabela mas não seria filtrável.
function populateCampaignFilter() {
  const sel = document.getElementById('campaignFilter');
  if (!sel) return;
  const known = new Set(Array.from(sel.options).map(o => o.value));
  const keys  = new Set();
  for (const r of CAMPAIGN_DAILY_DATA) {
    const base = BASE_CAMPS.find(c => r.campaign.toUpperCase().includes(c.name));
    keys.add(base ? base.name : r.campaign); // mesma chave usada em campTotals()
  }
  for (const k of keys) {
    if (known.has(k)) continue;
    const o = document.createElement('option');
    o.value = k;
    o.textContent = k.length > 30 ? k.slice(0, 30) + '…' : k;
    sel.appendChild(o);
    known.add(k);
  }
}

function mergeCostIntoAllDays() {
  // Soma custo de Ads (CSV) ao custo de bureau (já preenchido pelo Supabase)
  const costMap = new Map();
  const gadsConvMap = new Map(); // conversões reportadas pelo próprio Google Ads (métrica do Ads, não pedidos pagos)
  for (const r of CAMPAIGN_DAILY_DATA) {
    costMap.set(r.dateStr, (costMap.get(r.dateStr) || 0) + r.cost);
    gadsConvMap.set(r.dateStr, (gadsConvMap.get(r.dateStr) || 0) + r.conversions);
  }
  for (const d of ALL_DAYS) {
    d.cost      = costMap.get(d.dateStr) || 0;
    d.costTotal = +(d.cost + d.costBureau).toFixed(2);
    d.profit    = +(d.revenue - d.costTotal).toFixed(2);
    d.netProfit = +(d.revenue * netFactor(d.dateStr) - d.costTotal).toFixed(2);
    if (d.conv > 0 && d.cost      > 0) d.cac = +(d.cost      / d.conv).toFixed(2);
    if (d.conv > 0 && d.costTotal > 0) d.cpv = +(d.costTotal / d.conv).toFixed(2);
    // CAC "Google Ads" — custo Ads ÷ conversões reportadas pelo Ads (métrica própria, diferente de paid_orders real)
    d.gadsConv  = gadsConvMap.get(d.dateStr) || 0;
    d.cacAds    = d.gadsConv > 0 && d.cost > 0 ? +(d.cost / d.gadsConv).toFixed(2) : null;
  }
}

