// ─── EXAMPLE DATA (fallback when CSV_URL is empty or fetch fails) ─────────────
function makeDays() {
  const days = [];
  let seed = 42;
  function rand() { seed = (seed * 16807 + 0) % 2147483647; return (seed - 1) / 2147483646; }
  // Gera dados demo para o mês ATUAL (não mais fixo em março/2026) — usado só como
  // fallback se o Supabase falhar mesmo após retries em supaGet().
  const _now      = new Date();
  const _y        = _now.getFullYear();
  const _m        = _now.getMonth(); // 0-indexed
  const _daysInMo = new Date(_y, _m + 1, 0).getDate();
  const _pad      = n => String(n).padStart(2, '0');
  for (let i = 1; i <= _daysInMo; i++) {
    const date = new Date(_y, _m, i);
    const isWE = date.getDay() === 0 || date.getDay() === 6;
    const w    = isWE ? 0.56 + rand()*0.08 : 1.06 + rand()*0.14;
    days.push({ date, dateStr:`${_y}-${_pad(_m+1)}-${_pad(i)}`, weight:w, isWE,
                upsellRate: +(14 + rand()*16).toFixed(1) });
  }
  const totalW = days.reduce((s,d)=>s+d.weight,0);
  return days.map(d => {
    const frac    = d.weight / totalW;
    const cost    = +(MONTHLY.cost    * frac).toFixed(2);
    const conv    = +(MONTHLY.conv    * frac).toFixed(1);
    const revenue = +(MONTHLY.revenue * frac).toFixed(2);
    const profit  = +(revenue - cost).toFixed(2);
    const checkouts = +(conv / (MONTHLY.convRate / 100)).toFixed(1);
    const netProfit = +(revenue * netFactor(d.dateStr) - cost).toFixed(2);
    return { ...d, cost, conv, revenue, profit, netProfit, checkouts,
             cac: conv>0?+(cost/conv).toFixed(2):null };
  });
}

// ─── CSV PARSING ─────────────────────────────────────────────────────────────
function parseCSVLine(line) {
  const cols = []; let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') { inQ = !inQ; }
    else if (c === ',' && !inQ) { cols.push(cur.trim()); cur = ''; }
    else { cur += c; }
  }
  cols.push(cur.trim());
  return cols;
}

// Parse Brazilian-formatted numbers: "R$ 1.234,56" → 1234.56, "79,58" → 79.58
function parseBRL(s) {
  if (!s) return 0;
  s = String(s).replace(/"/g, '').trim();
  s = s.replace(/R\$\s*/i, '');           // strip currency symbol
  s = s.replace(/\./g, '');              // remove thousand separators (dots in BR)
  s = s.replace(',', '.');               // decimal comma → dot
  return parseFloat(s) || 0;
}

function parseCSVText(text) {
  const lines = text.replace(/\r\n/g,'\n').replace(/\r/g,'\n').trim().split('\n');
  if (lines.length < 2) return [];
  const headers = lines[0].split(',').map(h => h.trim().replace(/"/g,'').toLowerCase());
  const idx = name => headers.findIndex(h => h === name || h.startsWith(name));
  const cDate    = idx('data');       const cCostAds = idx('custo_ads');
  const cCostBur = idx('custo_bureau'); const cCostTot = idx('custo_total');
  const cRev     = idx('receita');    const cPed     = idx('pedidos');
  const cChk     = idx('checkouts');  const cPur     = idx('compras');
  const cLucro   = idx('lucro');      const cUpsellPct = idx('tx_upsell_pct');
  const cPedUpsell = idx('pedidos_upsell');
  if (cDate < 0) return [];
  const days = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = parseCSVLine(lines[i]);
    if (cols.length < 2) continue;
    const dateStr   = (cols[cDate] || '').replace(/"/g,'').trim();
    if (!dateStr || dateStr === 'data') continue;
    const cost        = parseBRL(cols[cCostAds]);
    const costBureau  = parseBRL(cols[cCostBur]);
    const costTotal   = cCostTot >= 0
      ? parseBRL(cols[cCostTot])
      : +(cost + costBureau).toFixed(2);
    const revenue     = parseBRL(cols[cRev]);
    const pedidos     = parseInt((cols[cPed] || '0').replace(/"/g,'')) || 0;
    const pedidosUpsell = cPedUpsell >= 0 ? (parseInt((cols[cPedUpsell]||'0').replace(/"/g,''))||0) : 0;
    const checkouts   = parseBRL(cols[cChk]);
    const conv        = pedidos; // usar pedidos (total de pedidos) como métrica de conversão
    const profit      = cLucro >= 0
      ? parseBRL(cols[cLucro])
      : +(revenue - costTotal).toFixed(2);
    const upsellRateRaw = cUpsellPct >= 0 ? (cols[cUpsellPct]||'').replace(/"/g,'').trim() : '';
    const upsellRate  = upsellRateRaw
      ? parseBRL(upsellRateRaw)
      : (pedidos > 0 && pedidosUpsell > 0 ? +(pedidosUpsell/pedidos*100).toFixed(2) : 0);
    const date        = new Date(dateStr + 'T00:00:00');
    days.push({ date, dateStr, cost, costBureau, costTotal,
                revenue, conv, profit,
                netProfit: +(revenue * netFactor(dateStr) - costTotal).toFixed(2),
                checkouts, upsellRate, pedidos, pedidosUpsell,
                cac: (conv>0 && cost>0)     ? +(cost     /conv).toFixed(2) : null,
                cpv: (conv>0 && costTotal>0)? +(costTotal/conv).toFixed(2) : null });
  }
  return days.sort((a,b) => a.dateStr.localeCompare(b.dateStr));
}

async function loadCSVData(url) {
  const resp = await fetch(url, { cache:'no-cache' });
  if (!resp.ok) throw new Error('HTTP ' + resp.status);
  return parseCSVText(await resp.text());
}

