// ─── DATE PICKER ─────────────────────────────────────────────────────────────
function toggleDP() {
  const dd  = document.getElementById('dateDD');
  const btn = document.querySelector('.date-picker-btn');
  if (window.innerWidth <= 600 && btn) {
    // fixed mode: position below the button
    const rect = btn.getBoundingClientRect();
    dd.style.top = (rect.bottom + 6) + 'px';
    // iOS Safari: position:fixed é clipado por ancestral com overflow scroll
    // (.header-row-controls tem overflow-x:auto no mobile) — mover pro body.
    if (dd.parentElement !== document.body) document.body.appendChild(dd);
  } else {
    dd.style.top = '';
    const wrap = document.getElementById('dpWrapper');
    if (dd.parentElement !== wrap) wrap.appendChild(dd);
  }
  dd.classList.toggle('open');
}
document.addEventListener('click', e => {
  const dd = document.getElementById('dateDD');
  if (!document.getElementById('dpWrapper').contains(e.target) && !dd.contains(e.target))
    dd.classList.remove('open');
});

// Tooltips (.has-tip/.tip-icon): no desktop já funcionam via :hover (CSS puro).
// No mobile não existe :hover, então o toque no ícone "i" alterna .tip-open —
// e qualquer toque fora fecha o que estiver aberto.
document.addEventListener('click', e => {
  const icon = e.target.closest('.tip-icon');
  const card = icon ? icon.closest('.has-tip') : null;
  document.querySelectorAll('.has-tip.tip-open').forEach(el => {
    if (el !== card) el.classList.remove('tip-open');
  });
  if (card) { e.stopPropagation(); card.classList.toggle('tip-open'); }
});

// ─── REFRESH ──────────────────────────────────────────────────────────────────
function refreshDashboard() {
  const btn = document.getElementById('refreshBtn');
  if (btn) btn.classList.add('loading');
  initDashboard().finally(() => { if (btn) btn.classList.remove('loading'); });
}
function setPreset(preset, label, e) {
  activePreset = preset;
  document.getElementById('dateLabel').textContent = label;
  document.querySelectorAll('.date-preset').forEach(el=>el.classList.remove('active'));
  e.currentTarget.classList.add('active');
  document.getElementById('customRange').classList.toggle('visible', preset==='custom');
  if (preset==='custom') return;
  const now = new Date();
  const pad = n => String(n).padStart(2,'0');
  const iso = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
  const today = iso(now);
  let fromDate, toDate = today;
  if (preset === 'today') {
    fromDate = today;
  } else if (preset === 'yesterday') {
    const d = new Date(now); d.setDate(d.getDate()-1); fromDate = toDate = iso(d);
  } else if (preset === 'week') {
    // Domingo como primeiro dia da semana
    const d = new Date(now); d.setDate(d.getDate() - d.getDay()); fromDate = iso(d);
  } else if (preset === '7d') {
    const d = new Date(now); d.setDate(d.getDate()-6); fromDate = iso(d);
  } else if (preset === '14d') {
    const d = new Date(now); d.setDate(d.getDate()-13); fromDate = iso(d);
  } else if (preset === '30d') {
    const d = new Date(now); d.setDate(d.getDate()-29); fromDate = iso(d);
  } else if (preset === '60d') {
    const d = new Date(now); d.setDate(d.getDate()-59); fromDate = iso(d);
  } else if (preset === '90d') {
    const d = new Date(now); d.setDate(d.getDate()-89); fromDate = iso(d);
  } else if (preset === 'month') {
    fromDate = today.slice(0,7)+'-01';
  } else if (preset === 'lastmonth') {
    const f = new Date(now.getFullYear(), now.getMonth()-1, 1);
    const t = new Date(now.getFullYear(), now.getMonth(), 0);
    fromDate = iso(f); toDate = iso(t);
  } else if (preset === 'ytd') {
    fromDate = `${now.getFullYear()}-01-01`;
  } else {
    fromDate = ALL_DAYS.length ? ALL_DAYS[0].dateStr : today;
  }
  filtered = ALL_DAYS.filter(d => d.dateStr >= fromDate && d.dateStr <= toDate);
  // Fallback para all data apenas quando não for filtro de dia exato
  if (!filtered.length && preset !== 'today' && preset !== 'yesterday') filtered = [...ALL_DAYS];
  document.getElementById('dateDD').classList.remove('open');
  try { sessionStorage.setItem('vp_filter', JSON.stringify({ preset, label, from:fromDate, to:toDate })); } catch(e){}
  render();
}
function applyCustomDate() {
  const f = document.getElementById('dateFrom').value, t = document.getElementById('dateTo').value;
  filtered = ALL_DAYS.filter(d=>d.dateStr>=f && d.dateStr<=t);
