  document.getElementById('dateLabel').textContent = lbl2;
  document.getElementById('dateDD').classList.remove('open');
  try { sessionStorage.setItem('vp_filter', JSON.stringify({ preset:'custom', label:lbl2, from:f, to:t })); } catch(e){}
  render();
}
function applyFilters() { activeCamp = document.getElementById('campaignFilter').value; render(); }

// Defaults do range personalizado: mês atual (1º dia → hoje). Se houver um
// filtro custom salvo na sessão, restaura as datas dele nos inputs.
(function initCustomRangeDefaults() {
  const fEl = document.getElementById('dateFrom'), tEl = document.getElementById('dateTo');
  if (!fEl || !tEl) return;
  const pad = n => String(n).padStart(2,'0');
  const now = new Date();
  const today = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
  let from = today.slice(0,7) + '-01', to = today;
  try {
    const saved = JSON.parse(sessionStorage.getItem('vp_filter'));
    if (saved && saved.preset === 'custom' && saved.from && saved.to) { from = saved.from; to = saved.to; }
  } catch(e){}
  fEl.value = from;
  tEl.value = to;
})();

// ─── TAX FACTOR ──────────────────────────────────────────────────────────────
// Fator líquido após imposto, por data de venda: 1 − imposto do mês / 100.
// Imposto (%) vem do módulo Metas (monthly_targets.tax_pct), com a mesma herança
// por campo das outras metas; sem valor cadastrado → TAX_PCT_DEFAULT (8%).
// (Até 30/09/2026 era faseado fixo no código: 0,92 / 0,95 / 0,962.)
function taxPctFor(dateStr) { return targetFor(dateStr).taxPct; }
function netFactor(dateStr) { return 1 - taxPctFor(dateStr) / 100; }

// Rótulo do imposto aplicado a um conjunto de dias: "8%" ou "3,8%–8%" se variar.
function taxLabel(days) {
  const f = v => Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 2 }) + '%';
  const vals = (days && days.length ? days : [{ dateStr: null }])
    .map(d => taxPctFor(d.dateStr || new Date().toISOString().slice(0, 10)));
  const mn = Math.min(...vals), mx = Math.max(...vals);
  return mn === mx ? f(mn) : f(mn) + '–' + f(mx);
}

// Recalcula netProfit por dia (após salvar imposto em Metas, sem recarregar a página).
function recomputeNetProfit() {
  for (const d of ALL_DAYS) {
    const c = d.costTotal != null ? d.costTotal : (d.cost || 0);
    d.netProfit = +(d.revenue * netFactor(d.dateStr) - c).toFixed(2);
  }
}

// ─── TOTALS ───────────────────────────────────────────────────────────────────
function totals() {
  const cf = activeCamp ? (BASE_CAMPS.find(c=>c.name===activeCamp)?.costShare||1) : 1;
  // Multiplicadores (cf*1.4/cf*1.1) são resquício dos dados demo: só se aplicam
  // no fallback sintético. Com dados reais os agregados não são fabricados —
  // o detalhamento real por campanha vem de campTotals()/CAMPAIGN_DAILY_DATA.
  const _demoCamp = !usingRealData && activeCamp;
  const revMul = _demoCamp ? cf*1.4 : 1, costMul = _demoCamp ? cf : 1, convMul = _demoCamp ? cf*1.1 : 1;
  const rev        = filtered.reduce((s,d)=>s+d.revenue,          0)*revMul;
  const cost       = filtered.reduce((s,d)=>s+d.cost,             0)*costMul; // só Ads
  const costBureau = filtered.reduce((s,d)=>s+(d.costBureau||0),  0)*costMul;
  const costTotal  = +(cost + costBureau).toFixed(2);
  const conv       = filtered.reduce((s,d)=>s+d.conv,             0)*convMul;
  const gadsConv   = filtered.reduce((s,d)=>s+(d.gadsConv||0),    0)*convMul;
  // Lucro real = receita − custo_ads − custo_bureau
  const pft        = usingRealData
    ? filtered.reduce((s,d)=>s+(d.profit||0), 0)*revMul
    : +(rev - costTotal).toFixed(2);
  // Upsell ponderado: Σ pedidos com upsell ÷ Σ pedidos (média simples de taxas
  // diárias distorcia — dia com 3 pedidos pesava igual a dia com 300).
  // Fallback demo mantém a média simples (makeDays não gera pedidosUpsell).
  const upsell     = usingRealData
    ? (conv > 0 ? filtered.reduce((s,d)=>s+(d.pedidosUpsell||0),0) / conv * 100 : 0)
    : (filtered.length ? filtered.reduce((s,d)=>s+d.upsellRate,0)/filtered.length : 0);
  const checkouts  = filtered.reduce((s,d)=>s+(d.checkouts||0),   0)*convMul;
  // Sem dados reais de checkout, convRate é null (o card mostra "—") — não usar
  // o MONTHLY.convRate congelado como se fosse real. No demo, mantém o fallback.
  const convRate   = checkouts > 0 ? (conv / checkouts * 100) : (usingRealData ? null : MONTHLY.convRate);
  // Lucro líquido: imposto do mês de cada dia (módulo Metas, padrão 8%) via netFactor()
  const netPftOpt   = +(filtered.reduce((s,d) =>
    s + d.revenue * revMul * netFactor(d.dateStr) - (d.costTotal||0) * costMul, 0)).toFixed(2);
  const netPft      = netPftOpt; // mesmo cálculo (antes: baseline fixo 0.92)
  const refundCount = filtered.reduce((s,d)=>s+(d.refundCount||0),0);
  const refundValue = +filtered.reduce((s,d)=>s+(d.refundValue||0),0).toFixed(2);
  const refundRate  = (conv+refundCount)>0 ? +(refundCount/(conv+refundCount)*100).toFixed(2) : 0;
  return { rev, cost, costBureau, costTotal, conv, gadsConv, pft, netPft, netPftOpt, refundCount, refundValue, refundRate,
           cac: conv>0 && cost>0     ? +(cost     /conv).toFixed(2) : 0,
           cacAds: gadsConv>0 && cost>0 ? +(cost   /gadsConv).toFixed(2) : 0,
           cpv: conv>0 && costTotal>0? +(costTotal/conv).toFixed(2) : 0,
           roas:costTotal>0?+(rev/costTotal).toFixed(2):0,
           margin:rev>0?pft/rev:0, ticket:conv>0?+(rev/conv).toFixed(2):0, convRate, upsell };
}
function campTotals() {
  // Bureau total do período (distribuído proporcionalmente à receita por campanha)
  const totalBureau = filtered.reduce((s,d) => s + (d.costBureau||0), 0);

  // ── Dados reais via CampaignDaily ──────────────────────────────────────────
  if (CAMPAIGN_DAILY_DATA.length > 0 && filtered.length > 0) {
    const minDate = filtered[0].dateStr, maxDate = filtered[filtered.length-1].dateStr;
    const agg = new Map();
    for (const r of CAMPAIGN_DAILY_DATA) {
      if (r.dateStr < minDate || r.dateStr > maxDate) continue;
      // Mapeia nome completo da campanha (ex: "[SEARCH]...[RISCO_DOC]...") → chave BASE_CAMPS.
      // Campanha fora de BASE_CAMPS NÃO é mais dropada: entra com o próprio nome
      // (antes o custo dela sumia silenciosamente da tabela Campanhas).
      const base = BASE_CAMPS.find(c => r.campaign.toUpperCase().includes(c.name));
      const key  = base ? base.name : r.campaign;
      if (activeCamp && key !== activeCamp) continue;
      const prev = agg.get(key) || { name:key, teste: !!(base && base.teste), cost:0, conv:0, rev:0 };
      prev.cost += r.cost;
      prev.conv += r.conversions;
      prev.rev  += r.revenue;
      agg.set(key, prev);
    }
    if (agg.size > 0) {
      const camps = Array.from(agg.values());
      // paid_orders real do período (pagamentos confirmados na Pagar.me) — não é segmentado por campanha no banco,
      // então distribuímos proporcionalmente à participação de conversões do Google Ads de cada campanha.
      // EXCEÇÃO — campanha do teste R$79,90: produto/ticket diferentes quebram o rateio
      // proporcional; com dados REAIS do teste (TESTE_DAILY, fase 2), a linha dela usa as
      // vendas reais do produto e as demais rateiam o restante. Com demo, rateio antigo.
      const testeReal   = TESTE_WIRED && !TESTE_DEMO;
      const diasTesteIn = testeReal ? TESTE_DAILY.filter(d => d.dateStr >= minDate && d.dateStr <= maxDate) : [];
      const vendasTeste = diasTesteIn.reduce((s,d) => s + d.vendas,  0);
      const recTeste    = diasTesteIn.reduce((s,d) => s + d.receita, 0);
      const totalPaidOrders = filtered.reduce((s,d) => s + d.conv, 0);
      const paidRestante    = testeReal ? Math.max(0, totalPaidOrders - vendasTeste) : totalPaidOrders;
      const totalGadsConv   = camps.reduce((s,c) => s + (testeReal && c.teste ? 0 : c.conv), 0);
      // Receita por campanha só existe pro teste (rateio de bureau por receita
      // usa apenas as demais — senão o teste, única linha com rev, levaria 100%)
      const totalRev = camps.reduce((s,c) => s + (testeReal && c.teste ? 0 : c.rev), 0);
      return camps.map(c => {
        const isTeste  = testeReal && c.teste;
        const rev      = isTeste ? recTeste : c.rev;
        // Bureau: teste usa estimativa própria por venda; demais proporcional à receita
        const bureauShare = isTeste
          ? vendasTeste * PRODUTO_TESTE.bureauPorVenda
          : (totalRev > 0 ? totalBureau * (c.rev / totalRev) : 0);
        const costTotal   = +(c.cost + bureauShare).toFixed(2);
        const pft         = +(rev - costTotal).toFixed(2);
        const gadsConv    = c.conv; // conversões reportadas pelo Google Ads (métrica própria do Ads)
        const realConv    = isTeste
          ? vendasTeste // vendas pagas REAIS do produto 79,90 (Supabase), não estimativa
          : (totalGadsConv > 0 ? paidRestante * (gadsConv / totalGadsConv) : 0);
        return {
          ...c, color: CAMP_COLORS[c.name] || '#6b6b6b',
          rev, costTotal, bureauShare: +bureauShare.toFixed(2),
          pft,
          gadsConv,
          conv: +realConv.toFixed(1), // CAC principal usa pedidos pagos reais (teste: exatos; demais: estimados por participação)
          cac:    realConv > 0 ? +(c.cost / realConv).toFixed(2) : 0,  // CAC real (pago)
          cacAds: gadsConv > 0 ? +(c.cost / gadsConv).toFixed(2) : 0,  // CAC Google Ads (métrica própria do Ads)
          roas: c.cost > 0 ? +(rev / c.cost).toFixed(2) : 0,
          convShare: 0, costShare: 0,
        };
      }).sort((a,b) => b.conv - a.conv);
    }
  }

  // ── Fallback: estimativas por proporção (quando CampaignDaily não disponível) ──
  return BASE_CAMPS
    .filter(c=>!c.teste) // teste fica fora do rateio demo (shares 0)
    .filter(c=>!activeCamp||c.name===activeCamp)
    .map(c=>{
      const cost    = filtered.reduce((s,d)=>s+d.cost,0)*c.costShare;
      const conv    = filtered.reduce((s,d)=>s+d.conv,0)*c.convShare;
      const rev     = conv*TICKET;
      const bureauShare = totalBureau * c.costShare; // estima bureau pela mesma proporção de custo
      const costTotal   = +(cost + bureauShare).toFixed(2);
      const pft = +(rev - costTotal).toFixed(2);
      return {...c, color:CAMP_COLORS[c.name], cost, costTotal, bureauShare:+bureauShare.toFixed(2),
              conv, rev, pft, cac:conv>0?cost/conv:0, cacAds:0, gadsConv:0, roas:cost>0?rev/cost:0};
    })
    .sort((a,b)=>b.conv-a.conv);
}

// ─── PERÍODO ANTERIOR ─────────────────────────────────────────────────────────
function prevTotals() {
  if (!filtered.length || ALL_DAYS.length === 0) return null;
  // Período anterior = janela de mesmo nº de DIAS DE CALENDÁRIO imediatamente
  // antes do início do período atual (slice(-n) pegava dias não contíguos
  // quando havia buracos no calendário).
  const _isoP    = dt => `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
  const fromCur  = new Date(filtered[0].dateStr + 'T00:00:00');
  const toCur    = new Date(filtered[filtered.length-1].dateStr + 'T00:00:00');
  const nDays    = Math.round((toCur - fromCur) / 86400000) + 1;
  const toPrevD   = new Date(fromCur); toPrevD.setDate(toPrevD.getDate() - 1);
  const fromPrevD = new Date(fromCur); fromPrevD.setDate(fromPrevD.getDate() - nDays);
  const fromPrev = _isoP(fromPrevD), toPrev = _isoP(toPrevD);
  const prev = ALL_DAYS.filter(d => d.dateStr >= fromPrev && d.dateStr <= toPrev);
  if (!prev.length) return null;
  const cf = activeCamp ? (BASE_CAMPS.find(c=>c.name===activeCamp)?.costShare||1) : 1;
  // Mesma regra de totals(): multiplicadores demo só sem dados reais
  const _demoCamp = !usingRealData && activeCamp;
  const costMul = _demoCamp?cf:1, revMul=_demoCamp?cf*1.4:1, convMul=_demoCamp?cf*1.1:1;
  const rev     = prev.reduce((s,d)=>s+d.revenue,         0)*revMul;
  const cost    = prev.reduce((s,d)=>s+d.cost,            0)*costMul;
  const costBur = prev.reduce((s,d)=>s+(d.costBureau||0), 0)*costMul;
  const costTot = +(cost+costBur).toFixed(2);
  const pft     = usingRealData ? prev.reduce((s,d)=>s+(d.profit||0),0)*revMul : +(rev-costTot).toFixed(2);
  const netPftOpt = +(prev.reduce((s,d) =>
    s + d.revenue * revMul * netFactor(d.dateStr) - (d.costTotal||0) * costMul, 0)).toFixed(2);
  const netPft    = netPftOpt; // mesmo cálculo (antes: baseline fixo 0.92)
  const conv    = prev.reduce((s,d)=>s+d.conv,            0)*convMul;
  const checks  = prev.reduce((s,d)=>s+(d.checkouts||0),  0)*convMul;
  const upsell  = usingRealData
    ? (conv > 0 ? prev.reduce((s,d)=>s+(d.pedidosUpsell||0),0) / conv * 100 : 0)
    : prev.reduce((s,d)=>s+d.upsellRate,      0)/(prev.length||1);
  const convRate= checks>0?(conv/checks*100):null;
  const cac     = conv>0 && cost>0    ? +(cost   /conv).toFixed(2) : 0;
  const cpv     = conv>0 && costTot>0 ? +(costTot/conv).toFixed(2) : 0;
  const roas    = costTot>0?+(rev/costTot).toFixed(2):0;
  const margin  = rev>0?pft/rev:0;
  return { rev, cost, costBureau:costBur, costTotal:costTot, pft, netPft, netPftOpt, conv, upsell, cac, cpv, roas, margin, convRate, ticket:conv>0?+(rev/conv).toFixed(2):0 };
}
function pctDelta(curr, prev, reverse) {
  if (prev==null || Math.abs(prev)<0.01) return null;
  const pct = ((curr-prev)/Math.abs(prev))*100;
  const cls = reverse ? (pct<-2?'pos':pct>2?'neg':'neu') : (pct>2?'pos':pct<-2?'neg':'neu');
  return { txt: (pct>=0?'↑':('↓'))+(Math.abs(pct).toFixed(1))+'% vs ant.', cls };
}

