// ─── BUREAU ASSERTIVA CARD ────────────────────────────────────────────────────
function buildBureauCard() {
  const card    = document.getElementById('bureauCard');
  const valEl   = document.getElementById('bureauCardValue');
  const badge   = document.getElementById('bureauCardBadge');
  const meta    = document.getElementById('bureauCardMeta');
  const spark   = document.getElementById('bureauCardSpark');
  const metrics = document.getElementById('bureauCardMetrics');
  if (!card) return;

  if (!ALL_DAYS.length) {
    valEl.textContent  = '—';
    badge.textContent  = 'sem dados';
    metrics.innerHTML  = '';
    return;
  }

  const fmtR = v => v.toLocaleString('pt-BR', { style:'currency', currency:'BRL', maximumFractionDigits:0 });
  const fmtN = (v, d=1) => v.toLocaleString('pt-BR', { minimumFractionDigits:d, maximumFractionDigits:d });

  const sorted = [...ALL_DAYS].sort((a,b) => a.dateStr.localeCompare(b.dateStr));
  const now    = new Date();
  const currMo = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  const prevMo = (() => {
    const d = new Date(now.getFullYear(), now.getMonth()-1, 1);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  })();

  const currDays = sorted.filter(d => d.dateStr.startsWith(currMo));
  const prevDays = sorted.filter(d => d.dateStr.startsWith(prevMo));

  // Acumulado mês atual
  const currTotal = currDays.reduce((s,d) => s + (d.costBureau||0), 0);

  // Total mês anterior
  const prevTotal = prevDays.reduce((s,d) => s + (d.costBureau||0), 0);

  // Projeção mês atual
  const daysInMonth  = new Date(now.getFullYear(), now.getMonth()+1, 0).getDate();
  const daysPassed   = currDays.filter(d => (d.costBureau||0) > 0).length || 1;
  const dailyAvg     = currTotal / daysPassed;
  const projection   = dailyAvg * daysInMonth;

  // Média 7d (exclui hoje em aberto → penúltimo ao antepenúltimo)
  const last7        = sorted.slice(-8, -1).filter(d => (d.costBureau||0) > 0);
  const avg7         = last7.length ? last7.reduce((s,d) => s+(d.costBureau||0), 0) / last7.length : 0;

  // Ontem
  const yesterday    = sorted.length >= 2 ? sorted[sorted.length - 2] : null;
  const yesterdayCost = yesterday?.costBureau || 0;

  // Spike diário
  const spikePct     = avg7 > 0 && yesterdayCost > 0 ? ((yesterdayCost - avg7) / avg7) * 100 : 0;
  const isSpike      = spikePct >= 30;

  // Variação mês vs anterior
  const projVsPrev   = prevTotal > 0 ? ((projection - prevTotal) / prevTotal) * 100 : null;

  // Valor principal = acumulado mês
  valEl.textContent = fmtR(currTotal);

  // Badge
  let badgeClass, badgeText;
  if (isSpike)                         { badgeClass = 'spike'; badgeText = `📈 Spike +${fmtN(spikePct)}%`; }
  else if (projVsPrev !== null && projVsPrev > 40) { badgeClass = 'aviso'; badgeText = `⚠️ Proj. +${fmtN(projVsPrev)}%`; }
  else                                 { badgeClass = 'ok';    badgeText = '✅ Normal'; }
  badge.className   = 'bureau-card-badge ' + badgeClass;
  badge.textContent = badgeText;

  // Meta
  meta.textContent = `${daysPassed} de ${daysInMonth} dias`;

  // Sparkline (custo bureau por dia no mês atual)
  const sparkVals   = currDays.map(d => d.costBureau||0);
  const sparkMax    = Math.max(...sparkVals, 1);
  const sparkColor  = isSpike ? '#f97316' : '#7c3aed';
  spark.innerHTML   = sparkVals.slice(-20).map(v => {
    const h = Math.max(2, Math.round((v / sparkMax) * 24));
    return `<span style="height:${h}px;background:${sparkColor}"></span>`;
  }).join('');

  // 4 métricas
  const daysClass = d => d === null ? '' : d <= 3 ? 'danger' : d <= 7 ? 'warn' : 'good';

  const metricItems = [
    {
      label: 'Média diária (7d)',
      value: avg7 > 0 ? fmtR(avg7) : '—',
      sub:   `${daysPassed}d com dados no mês`,
      cls:   '',
    },
    {
      label: 'Projeção mês completo',
      value: fmtR(projection),
      sub:   projVsPrev !== null
        ? (projVsPrev > 0 ? `▲ ${fmtN(projVsPrev)}% vs mês ant.` : `▼ ${fmtN(Math.abs(projVsPrev))}% vs mês ant.`)
        : 'sem histórico anterior',
      cls:   projVsPrev !== null && projVsPrev > 40 ? 'warn' : projVsPrev !== null && projVsPrev > 0 ? '' : 'good',
    },
    {
      label: 'Bureau % da receita',
      value: (() => {
        const currRev = currDays.reduce((s,d) => s + (d.revenue||0), 0);
        return currRev > 0 ? fmtN((currTotal / currRev) * 100) + '%' : '—';
      })(),
      sub: (() => {
        const currRev = currDays.reduce((s,d) => s + (d.revenue||0), 0);
        const prevRev = prevDays.reduce((s,d) => s + (d.revenue||0), 0);
        const currPct = currRev > 0 ? (currTotal / currRev) * 100 : null;
        const prevPct = prevRev > 0 && prevTotal > 0 ? (prevTotal / prevRev) * 100 : null;
        if (currPct === null) return 'sem dados de receita';
        if (prevPct === null) return `mês ant.: ${fmtR(prevTotal)}`;
        const diff = currPct - prevPct;
        return `${diff > 0 ? '▲' : '▼'} ${fmtN(Math.abs(diff))}pp vs mês ant. (${fmtN(prevPct)}%)`;
      })(),
      cls: (() => {
        const currRev = currDays.reduce((s,d) => s + (d.revenue||0), 0);
        const pct = currRev > 0 ? (currTotal / currRev) * 100 : 0;
        return pct > 15 ? 'warn' : pct > 20 ? 'danger' : '';
      })(),
    },
    {
      label: 'Gasto ontem',
      value: yesterdayCost > 0 ? fmtR(yesterdayCost) : '—',
      sub:   avg7 > 0 && yesterdayCost > 0
        ? (spikePct > 10 ? `▲ ${fmtN(spikePct)}% acima da média` : spikePct < -10 ? `▼ ${fmtN(Math.abs(spikePct))}% abaixo da média` : '≈ dentro da média 7d')
        : 'sem histórico',
      cls:   isSpike ? 'warn' : '',
    },
  ];

  metrics.innerHTML = metricItems.map(m => `
    <div class="ads-bal-metric ${m.cls}">
      <div class="ads-bal-metric-label">${m.label}</div>
      <div class="ads-bal-metric-value">${m.value}</div>
      <div class="ads-bal-metric-sub">${m.sub}</div>
    </div>`).join('');

  buildBureauTypeGrid();
}

// ─── BUREAU POR TIPO (Assertiva vs CheckTudo) — split dentro do card principal ─
const BUREAU_TYPE_LABELS = { assertiva: 'Assertiva', checktudo: 'CheckTudo' };
const BUREAU_TYPE_COLORS = { assertiva: '#7c3aed', checktudo: '#0891b2' };

function buildBureauTypeGrid() {
  const grid = document.getElementById('bureauTypeCardGrid');
  if (!grid) return;

  if (!BUREAU_TYPE_ROWS.length) {
    grid.innerHTML = '<div class="bureau-card-meta">sem dados (tabela bureau_by_type_daily vazia)</div>';
    return;
  }

  const fmtR = v => v.toLocaleString('pt-BR', { style:'currency', currency:'BRL', maximumFractionDigits:0 });
  const fmtN = (v, d=1) => v.toLocaleString('pt-BR', { minimumFractionDigits:d, maximumFractionDigits:d });

  const now    = new Date();
  const currMo = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  const currRows = BUREAU_TYPE_ROWS.filter(r => String(r.date).slice(0,7) === currMo);

  // Agrupa por bureau
  const byBureau = new Map();
  for (const r of currRows) {
    const key = r.bureau || 'assertiva';
    const acc = byBureau.get(key) || { custo: 0, vendido: 0, dias: new Set() };
    acc.custo   += parseFloat(r.custo_bureau) || 0;
    acc.vendido += parseFloat(r.vendido_real) || 0;
    acc.dias.add(String(r.date).slice(0,10));
    byBureau.set(key, acc);
  }

  const totalCusto = [...byBureau.values()].reduce((s,v) => s + v.custo, 0);

  const daysInMonth = new Date(now.getFullYear(), now.getMonth()+1, 0).getDate();

  const order = ['assertiva', 'checktudo'];
  const keys  = [...byBureau.keys()].sort((a,b) => order.indexOf(a) - order.indexOf(b));

  grid.innerHTML = keys.map(key => {
    const acc     = byBureau.get(key);
    const label   = BUREAU_TYPE_LABELS[key] || key;
    const color   = BUREAU_TYPE_COLORS[key] || '#6b7280';
    const pct     = totalCusto > 0 ? (acc.custo / totalCusto) * 100 : 0;
    const dailyAvg   = acc.dias.size ? acc.custo / acc.dias.size : 0;
    const projection = dailyAvg * daysInMonth;
    const pctReceita = acc.vendido > 0 ? (acc.custo / acc.vendido) * 100 : 0;
    return `
      <div class="bureau-type-item">
        <div class="bureau-type-name">${label}</div>
        <div class="bureau-type-value">${fmtR(acc.custo)}</div>
        <div class="bureau-type-sub">${fmtN(pct)}% do custo total · proj. mês: ${fmtR(projection)}</div>
        <div class="bureau-type-sub">${fmtN(pctReceita)}% do vendido nesse bureau</div>
        <div class="bureau-type-bar"><div class="bureau-type-bar-fill" style="width:${Math.min(100,pct)}%;background:${color}"></div></div>
      </div>`;
  }).join('');
}

// ─── SALDO GOOGLE ADS ─────────────────────────────────────────────────────────
function buildAdsBalance() {
  const card    = document.getElementById('adsBalanceCard');
  const valEl   = document.getElementById('adsBalanceValue');
  const badge   = document.getElementById('adsBalanceBadge');
  const meta    = document.getElementById('adsBalanceMeta');
  const spark   = document.getElementById('adsBalanceSpark');
  const metrics = document.getElementById('adsBalanceMetrics');
  if (!card) return;

  if (!ADS_BALANCE_DATA.length) {
    valEl.textContent    = '—';
    badge.textContent    = 'sem dados';
    badge.className      = 'ads-balance-badge ok';
    meta.textContent     = 'Execute o cron para carregar';
    metrics.innerHTML    = '';
    return;
  }

  // ── Saldo atual ────────────────────────────────────────────────────────
  const latest = ADS_BALANCE_DATA[0];
  const bal    = parseFloat(latest.balance_brl) || 0;
  valEl.textContent = bal.toLocaleString('pt-BR', { style:'currency', currency:'BRL' });

  // ── Burn rate provisório para o badge (será recalculado abaixo) ──────────
  const _sorted   = [...ALL_DAYS].sort((a,b) => a.dateStr.localeCompare(b.dateStr));
  const _last7    = _sorted.slice(-8, -1).filter(d => d.cost > 0);
  const _avg7pre  = _last7.length ? _last7.reduce((s,d) => s + d.cost, 0) / _last7.length : 0;
  const _daysEst  = _avg7pre > 0 ? bal / _avg7pre : null;

  // ── Status badge — baseado em dias restantes (não em R$) ─────────────
  let statusClass, statusText;
  if      (_daysEst !== null && _daysEst <= 3) { statusClass = 'critico'; statusText = '🔴 Crítico — ' + _daysEst.toFixed(1) + 'd restantes'; }
  else if (_daysEst !== null && _daysEst <= 5) { statusClass = 'atencao'; statusText = '🟠 Atenção — ' + _daysEst.toFixed(1) + 'd restantes'; }
  else if (_daysEst !== null && _daysEst <= 7) { statusClass = 'aviso';   statusText = '🟡 Aviso — ' + _daysEst.toFixed(1) + 'd restantes'; }
  else                                          { statusClass = 'ok';      statusText = '✅ Saldo OK'; }
  badge.className   = 'ads-balance-badge ' + statusClass;
  badge.textContent = statusText;
  card.classList.toggle('pulse-critico', statusClass === 'critico');

  // ── Última atualização ─────────────────────────────────────────────────
  // Parse defensivo: Safari retorna Invalid Date para "YYYY-MM-DD HH:MM:SS"
  // (sem o "T"). Normaliza antes de converter.
  const _rawCheckedAt = typeof latest.checked_at === 'string' && !latest.checked_at.includes('T')
    ? latest.checked_at.replace(' ', 'T')
    : latest.checked_at;
  const checkedAt = new Date(_rawCheckedAt);
  const diffMin   = Math.round((Date.now() - checkedAt.getTime()) / 60000);
  meta.textContent = diffMin < 60
    ? `Atualizado há ${diffMin} min`
    : `Atualizado há ${Math.round(diffMin / 60)}h`;

  // ── Sparkline (histórico de saldo, cronológico) ────────────────────────
  const vals     = [...ADS_BALANCE_DATA].reverse().map(r => parseFloat(r.balance_brl) || 0);
  const maxVal   = Math.max(...vals, 1);
  const barColor = statusClass === 'critico' ? '#dc2626'
                 : statusClass === 'atencao' ? '#f97316'
                 : statusClass === 'aviso'   ? '#eab308'
                 : '#2563eb';
  spark.innerHTML = vals.slice(-20).map(v => {
    const h = Math.max(2, Math.round((v / maxVal) * 24));
    return `<span style="height:${h}px;background:${barColor}"></span>`;
  }).join('');

  // ── Cálculos de burn rate com base em ALL_DAYS ─────────────────────────
  const fmtR = v => v.toLocaleString('pt-BR', { style:'currency', currency:'BRL', maximumFractionDigits:0 });
  const fmtN = (v, d=1) => v.toLocaleString('pt-BR', { minimumFractionDigits:d, maximumFractionDigits:d });

  // Média de gasto diário (últimos 7 e 30 dias, excluindo dias com custo zero)
  const sortedDays  = [...ALL_DAYS].sort((a,b) => a.dateStr.localeCompare(b.dateStr));
  const last7days   = sortedDays.slice(-7).filter(d => d.cost > 0);
  const last30days  = sortedDays.slice(-30).filter(d => d.cost > 0);
  const avg7  = last7days.length  ? last7days.reduce((s,d)  => s + d.cost, 0) / last7days.length  : 0;
  const avg30 = last30days.length ? last30days.reduce((s,d) => s + d.cost, 0) / last30days.length : 0;
  const avgRef = avg7 > 0 ? avg7 : avg30; // prefere 7d; fallback 30d

  // Dias restantes e data estimada de esgotamento
  const daysLeft    = avgRef > 0 ? bal / avgRef : null;
  const runoutDate  = daysLeft !== null
    ? new Date(Date.now() + daysLeft * 86400000)
    : null;
  const runoutStr   = runoutDate
    ? runoutDate.toLocaleDateString('pt-BR', { day:'2-digit', month:'2-digit' })
    : '—';

  // Tendência: gasto ontem vs média 7d
  const yesterday   = sortedDays.length >= 2 ? sortedDays[sortedDays.length - 2] : null;
  const todayDay    = sortedDays.length >= 1  ? sortedDays[sortedDays.length - 1]  : null;
  const spendYest   = yesterday?.cost || 0;
  const spendToday  = todayDay?.cost  || 0;
  const burnVsAvg   = avg7 > 0 ? ((spendYest - avg7) / avg7) * 100 : 0;

  // Classe de urgência para dias restantes
  const daysClass = daysLeft === null ? '' : daysLeft <= 3 ? 'danger' : daysLeft <= 7 ? 'warn' : 'good';

  // ── Renderizar 4 métricas ──────────────────────────────────────────────
  const metricItems = [
    {
      label: 'Gasto médio / dia',
      value: avg7 > 0 ? fmtR(avg7) : '—',
      sub:   avg30 > 0 ? `30d: ${fmtR(avg30)}` : 'sem dados suficientes',
      cls:   '',
    },
    {
      label: 'Dias restantes',
      value: daysLeft !== null ? fmtN(daysLeft, 1) + ' dias' : '—',
      sub:   daysLeft !== null
        ? (daysLeft <= 3 ? '⚠️ Recarregue agora!' : daysLeft <= 7 ? '⚠️ Recarregue em breve' : 'campanha segura')
        : 'gasto insuficiente p/ calcular',
      cls:   daysClass,
    },
    {
      label: 'Esgotamento estimado',
      value: runoutStr,
      sub:   daysLeft !== null ? `em ${Math.floor(daysLeft)}d ${Math.round((daysLeft % 1) * 24)}h` : '—',
      cls:   daysClass,
    },
    {
      label: 'Gasto ontem',
      value: spendYest > 0 ? fmtR(spendYest) : '—',
      sub:   avg7 > 0 && spendYest > 0
        ? (burnVsAvg > 10 ? `▲ ${fmtN(burnVsAvg)}% acima da média` : burnVsAvg < -10 ? `▼ ${fmtN(Math.abs(burnVsAvg))}% abaixo da média` : `≈ dentro da média 7d`)
        : 'sem histórico',
      cls:   burnVsAvg > 20 ? 'warn' : '',
    },
  ];

  metrics.innerHTML = metricItems.map(m => `
    <div class="ads-bal-metric ${m.cls}">
      <div class="ads-bal-metric-label">${m.label}</div>
      <div class="ads-bal-metric-value">${m.value}</div>
      <div class="ads-bal-metric-sub">${m.sub}</div>
    </div>`).join('');
}

