    { id:'up', label:'Taxa de Upsell',   value:fmtN(T.upsell,1)+'%',   delta:d(T.upsell,P?.upsell,false),   sub:'meta: '+TGT.upsell+'%', color:T.upsell>=TGT.upsell?'green':'amber', dir:T.upsell>=TGT.upsell?'up':'neutral', badge:T.upsell>=TGT.upsell?'meta atingida':fmtN(TGT.upsell-T.upsell,1)+'pp abaixo', spark:filtered.map(x=>x.upsellRate), sc:'#7c3aed', targetPct:_tgtUpsell, tip:'pedidos com upsell ÷ total de pedidos\n(% que adicionou produto extra)' },
