// Iguala a altura de todos os itens de cada container ao maior deles — só no
// mobile (empilhado em 1-2 colunas, onde linhas de grid diferentes podem ter
// alturas diferentes entre si). No desktop (grid de 5 colunas) não faz nada:
// devolve os cards ao natural (min-height limpo) porque ali já ficam parecidos
// e forçar altura do maior desperdiçaria espaço em telas largas.
function equalizeCardHeights(containerSelector, itemSelector, opts) {
  const always = !!(opts && opts.always);
  const isMobile = window.innerWidth <= 900;
  document.querySelectorAll(containerSelector).forEach(container => {
    const items = [...container.querySelectorAll(itemSelector)];
    if (!items.length) return;
    items.forEach(el => { el.style.minHeight = ''; });
    if (!always && !isMobile) return;
    requestAnimationFrame(() => {
      const max = Math.max(...items.map(el => el.offsetHeight));
      items.forEach(el => { el.style.minHeight = max + 'px'; });
    });
  });
}

let _equalizeResizeTimer = null;
window.addEventListener('resize', () => {
  clearTimeout(_equalizeResizeTimer);
  _equalizeResizeTimer = setTimeout(() => {
    equalizeCardHeights('#kpiRow1, #kpiRow2, #kpiRow3', '.kpi-card');
    equalizeCardHeights('#gaugeRow', '.gauge-card');
    equalizeCardHeights('#view-campanhas .grid-1-1', '.card');
    equalizeCardHeights('#todayPace', '.pace-stat', { always: true });
    equalizeCardHeights('#lostIsTree', '.lit-box', { always: true });
  }, 150);
});

function renderRow(rowId, defs) {
  const row = document.getElementById(rowId);
  const hasSkel = row.firstChild && row.firstChild.classList && row.firstChild.classList.contains('kpi-skel');
  if (row.children.length !== defs.length || hasSkel) {
    row.innerHTML = '';
    defs.forEach(k => {
      const el = document.createElement('div');
      el.className = 'kpi-card'+(k.tip?' has-tip':''); el.id = 'kc_'+k.id;
      if (k.tip) el.setAttribute('data-tip', k.tip);
      el.innerHTML = `
        ${k.tip ? '<button type="button" class="tip-icon" aria-label="Mais informações sobre '+k.label+'">i</button>' : ''}
        <div class="kpi-top">
          <span class="kpi-label">${k.label}</span>
          <span class="badge ${k.dir}" id="kb_${k.id}"></span>
        </div>
        <div class="kpi-value" id="kv_${k.id}"></div>
        <div class="kpi-value-secondary" id="kv2_${k.id}" style="display:none"></div>
        <div id="kd_${k.id}" class="kpi-delta"></div>
        <div class="kpi-spark-wrap"><canvas id="ks_${k.id}"></canvas></div>
        <div class="kpi-tgt" id="kt_${k.id}" style="display:none"><div class="kpi-tgt-fill" id="ktf_${k.id}"></div></div>
        <div class="kpi-sub" id="ksub_${k.id}"></div>
        <div class="kpi-accent ${k.color}" id="ka_${k.id}"></div>`;
      row.appendChild(el);
    });
  }
  defs.forEach(k => {
    document.getElementById('kv_'+k.id).textContent   = k.value;
    const v2El = document.getElementById('kv2_'+k.id);
    if (k.secondary) { v2El.innerHTML = k.secondary; v2El.style.display = ''; }
    else { v2El.style.display = 'none'; }
    document.getElementById('ksub_'+k.id).textContent = k.sub;
    const b = document.getElementById('kb_'+k.id);
    b.textContent = (k.dir==='up'?'↑':k.dir==='down'?'↓':'→')+' '+k.badge;
    b.className   = 'badge '+k.dir;
    document.getElementById('ka_'+k.id).className = 'kpi-accent '+k.color;
    // Delta vs previous period
    const deltaEl = document.getElementById('kd_'+k.id);
    if (deltaEl) {
      if (k.delta) { deltaEl.textContent = k.delta.txt; deltaEl.className = 'kpi-delta '+k.delta.cls; }
      else         { deltaEl.textContent = '';           deltaEl.className = 'kpi-delta'; }
    }
    // Alert pulse border
    const card = document.getElementById('kc_'+k.id);
    if (card) card.classList.toggle('alert-pulse', !!k.alert);
    // Target progress bar
    const tgtWrap = document.getElementById('kt_'+k.id);
    const tgtFill = document.getElementById('ktf_'+k.id);
    if (tgtWrap && tgtFill) {
      if (k.targetPct != null && k.targetPct > 0) {
        tgtWrap.style.display = 'block';
        const pct = Math.min(110, Math.max(0, k.targetPct));
        const col = k.targetReverse
          ? (pct > 100 ? 'var(--red)' : pct > 85 ? 'var(--amber)' : 'var(--green)')
          : (pct >= 80 ? 'var(--green)' : pct >= 50 ? 'var(--amber)' : 'var(--red)');
        tgtFill.style.width   = pct + '%';
        tgtFill.style.background = col;
      } else {
        tgtWrap.style.display = 'none';
      }
    }
    drawSpark('ks_'+k.id, k.spark, k.sc);
  });
}

function drawSpark(id, data, color) {
  if (sparkRefs[id]) { sparkRefs[id].destroy(); delete sparkRefs[id]; }
  const canvas = document.getElementById(id);
  if (!canvas) return;
  const vals = data.filter(v=>v!==null&&!isNaN(v));
  if (!vals.length) return;
  sparkRefs[id] = new Chart(canvas, {
    type:'line',
    data:{ labels:vals.map((_,i)=>i), datasets:[{ data:vals, borderColor:color, borderWidth:1.5, pointRadius:0, fill:false, tension:.35 }] },
    options:{ responsive:true, maintainAspectRatio:false, animation:false,
      plugins:{ legend:{display:false}, tooltip:{enabled:false}, datalabels:{display:false} },
      scales:{ x:{display:false}, y:{display:false} } }
  });
}

// ─── GAUGES ───────────────────────────────────────────────────────────────────
function buildGauges(T) {
  // Budget pacing: estimate monthly spend from current period
  const now = new Date();
  const dayOfMonth = now.getDate();
  const daysInMonth = new Date(now.getFullYear(), now.getMonth()+1, 0).getDate();
  // Sum all days in current month from ALL_DAYS
  const moStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
  const moSpent = ALL_DAYS.filter(d => d.dateStr >= moStart).reduce((s,d) => s+(d.cost||0), 0);
  const TGT = activeTargets();            // metas do mês corrente do filtro
  const moTgt = targetFor(moStart);       // pacing compara sempre com o mês de HOJE
  const pacingBudget = moTgt.budget > 0 ? moTgt.budget : 1;
  const budgetPct = Math.min(100, (moSpent / pacingBudget) * 100);
  const idealPct  = Math.min(100, (dayOfMonth / daysInMonth) * 100);
  const budgetColor = budgetPct > idealPct + 10 ? '#dc2626' : budgetPct < idealPct - 15 ? '#d97706' : '#16a34a';

  const gs = [
    { label:'Eficiência de CAC', val:fmtR(T.cac), pct:Math.min(100,(TGT.cpa/Math.max(T.cac,.01))*100),
      color:T.cac<=TGT.cpa?'#16a34a':T.cac<=TGT.cpa*1.2?'#d97706':'#dc2626',
      sub:`Meta: ${fmtR(TGT.cpa)} · ${T.cac<=TGT.cpa?'✓ Dentro':'⚠ Acima da meta'}`,
      tip:'CAC do período ÷ meta do mês (monthly_targets). Barra cheia = CAC igual ou melhor que a meta.' },
    { label:'Margem de Contribuição', val:fmtN(T.margin*100,1)+'%', pct:Math.min(100,(T.margin*100/30)*100),
      color:T.margin>=.22?'#16a34a':'#d97706', sub:`Meta: 30% · Atual: ${fmtN(T.margin*100,1)}%`,
      tip:'Lucro bruto ÷ receita, sobre uma meta de referência de 30%.' },
    { label:'Taxa de Upsell', val:fmtN(T.upsell,1)+'%', pct:TGT.upsell>0?Math.min(100,(T.upsell/TGT.upsell)*100):0,
      color:T.upsell>=TGT.upsell?'#16a34a':'#7c3aed', sub:`Meta: ${TGT.upsell}% · ${T.upsell>=TGT.upsell?'✓ Atingido':'⚠ Abaixo'}`,
      tip:'% de pedidos com upsell sobre o total, comparado à meta do mês (monthly_targets).' },
    { label:'Pacing do Orçamento', val:fmtR(moSpent), pct: budgetPct,
      color: budgetColor,
      sub:`Orçamento: ${fmtR(pacingBudget)} · Ideal: ${idealPct.toFixed(0)}% · Realizado: ${budgetPct.toFixed(0)}%`,
      tip:'Gasto do mês até hoje ÷ orçamento mensal, comparado ao ritmo ideal (dias corridos ÷ dias do mês).' },
  ];
  const row = document.getElementById('gaugeRow');
  if (row.children.length !== gs.length) {
    row.innerHTML = '';
    gs.forEach((g,i) => {
      const d = document.createElement('div'); d.className = 'gauge-card has-tip'; d.dataset.tip = g.tip;
      d.innerHTML = `<button type="button" class="tip-icon" aria-label="Mais informações">i</button>
        <div class="gauge-lbl" id="gl${i}"></div>
        <div class="gauge-row2"><div class="gauge-track"><div class="gauge-fill" id="gf${i}"></div></div><div class="gauge-num" id="gn${i}"></div></div>
        <div class="gauge-sub" id="gs${i}"></div>`;
      row.appendChild(d);
    });
  }
  gs.forEach((g,i) => {
    document.getElementById('gl'+i).textContent = g.label;
    document.getElementById('gn'+i).textContent = g.val;
    document.getElementById('gn'+i).style.color = g.color;
    document.getElementById('gs'+i).textContent = g.sub;
    const f = document.getElementById('gf'+i);
    f.style.width = g.pct+'%'; f.style.background = g.color;
  });
  equalizeCardHeights('#gaugeRow', '.gauge-card');
}

// ─── ALERT ────────────────────────────────────────────────────────────────────
function buildAlertBar(T) {
  const bar = document.getElementById('alertBar');
  const msgs = [];
  const TGT = activeTargets();
  if (T.cac > TGT.cpa*1.15)
    msgs.push(`<strong>CAC alto:</strong> ${fmtR(T.cac)}<br>${fmtN((T.cac/TGT.cpa-1)*100,0)}% acima da meta de ${fmtR(TGT.cpa)}`);
  if (T.roas < 1)
    msgs.push(`<strong>ROAS crítico:</strong> ${fmtN(T.roas,2,'')}× — cada R$1 investido retorna menos de R$1`);
  if (msgs.length) {
    bar.style.display = 'flex';
    document.getElementById('alertText').innerHTML = msgs.join(' &nbsp;·&nbsp; ');
  } else { bar.style.display = 'none'; }
}

// ─── POR PRODUTO — TESTE PACOTE COMPLETO R$79,90 ─────────────────────────────
// Painel de leitura isolada do teste. Fonte real: view revenue_daily_completa
// (migration 014, Supabase da dash) + checkouts_campaign_daily (Supabase do
// site, cross-check por utm) + custo por campMatch em CAMPAIGN_DAILY_DATA —
// tudo montado em loadSupabaseData() → TESTE_DAILY/TESTE_WIRED. O demo abaixo
// é só fallback visual enquanto as views não respondem (chip "DADOS DEMO").
function makeTesteDemoDays() {
  // Determinístico (mesmo seed → mesmos números) — só pra aprovação visual.
  let seed = 7;
  const rand = () => { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
  const out = [];
  const end = new Date();
  for (let i = 13; i >= 0; i--) {
    const dt = new Date(end); dt.setDate(dt.getDate() - i);
    const dateStr = `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
    const dia     = 14 - i;                                    // dia 1..14 do teste
    const budget  = 150 + Math.min(dia * 8, 70) + rand() * 40; // orçamento sobe até ~R$260/dia
    const cacDia  = 72 - dia * 1.6 + (rand() - .5) * 14;       // CAC melhora com o learning
    const vendas  = Math.max(0, Math.round(budget / Math.max(cacDia, 35)));
    const vendasUtm = Math.max(0, vendas - (rand() < .12 ? 1 : 0)); // ~95% chegam com utm da campanha
    out.push({ dateStr, vendas, receita:+(vendas * PRODUTO_TESTE.preco).toFixed(2),
               custoAds:+budget.toFixed(2), vendasUtm });
  }
  return out;
}

function cacStatusTeste(cac) {
  // Classifica o CAC contra a régua do benchmark
  const P = PRODUTO_TESTE;
  if (cac == null)          return { cls:'',     txt:'—' };
  if (cac <= P.cacMetaMax)  return { cls:'ok',   txt:'✅ Dentro da meta' };
  if (cac <= P.cacEmpate)   return { cls:'warn', txt:'🟡 Entre meta e empate' };
  if (cac <= P.cacBreakEven)return { cls:'warn', txt:'🟠 Acima do empate' };
  return                           { cls:'bad',  txt:'🔴 Acima do break-even' };
}

function buildReguaTeste(cac) {
  const P = PRODUTO_TESTE, max = P.reguaMax;
  const pct = v => Math.max(0, Math.min(100, v / max * 100));
  const zonas = [
    { from:0,              to:P.cacMetaMin,   c:'rgba(22,163,74,.15)'  }, // abaixo da meta: bom
    { from:P.cacMetaMin,   to:P.cacMetaMax,   c:'rgba(22,163,74,.42)'  }, // faixa-alvo (meta)
    { from:P.cacMetaMax,   to:P.cacEmpate,    c:'rgba(217,119,6,.32)'  }, // meta→empate
    { from:P.cacEmpate,    to:P.cacBreakEven, c:'rgba(234,88,12,.30)'  }, // empate→break-even: perde eficiência
    { from:P.cacBreakEven, to:max,            c:'rgba(220,38,38,.28)'  }, // acima do break-even: prejuízo
  ];
  document.getElementById('ptReguaZonas').innerHTML =
    zonas.map(z => `<span style="width:${pct(z.to)-pct(z.from)}%;background:${z.c}"></span>`).join('');
  document.getElementById('ptReguaTicks').innerHTML =
    [...new Set([P.cacMetaMin, P.cacMetaMax, P.cacEmpate, P.cacBreakEven])] // dedupe: metaMax pode = empate
    .map(v => `<span style="left:${pct(v)}%">${v}</span>`).join('');
  document.getElementById('ptReguaCaption').textContent =
    `meta ${P.cacMetaMin}–${P.cacMetaMax} · empate ${P.cacEmpate} · break-even ${P.cacBreakEven} (bureau real ${fmtN(P.bureauPorVenda,2,'R$')}/venda)`;
  const mk = document.getElementById('ptReguaMarker');
  if (cac == null) { mk.style.display = 'none'; return; }
  mk.style.display = 'block';
  mk.style.left = pct(cac) + '%';
  mk.setAttribute('data-val', fmtN(cac, 2, 'R$'));
}

function buildProdutoTeste(T) {
  const card = document.getElementById('produtoTesteCard');
  if (!card) return;
  // NUNCA mostrar número fictício em produção: sem dados reais, o painel fica
  // VAZIO dizendo o que falta. Demo visual só com ?demoTeste=1 na URL (preview
  // local de design) — jamais como fallback automático.
  const _demoForcado = (() => { try { return new URLSearchParams(location.search).has('demoTeste'); } catch (e) { return false; } })();
  if (_demoForcado && !TESTE_WIRED && !TESTE_DAILY.length) { TESTE_DAILY = makeTesteDemoDays(); TESTE_DEMO = true; }
  const chip = document.getElementById('produtoDemoChip');
  if (chip) {
    if (TESTE_DEMO) { chip.style.display = 'inline-flex'; chip.textContent = 'DADOS DEMO (?demoTeste=1) — não são números reais'; }
    else if (!TESTE_WIRED) { chip.style.display = 'inline-flex'; chip.textContent = 'AGUARDANDO SETUP · rodar views SQL (instrucoes-teste-pacote-completo.md)'; }
    else chip.style.display = 'none';
  }

  const P  = PRODUTO_TESTE;
  const f0 = filtered.length ? filtered[0].dateStr : null;
  const f1 = filtered.length ? filtered[filtered.length-1].dateStr : null;
  // Interseção do teste com o filtro de data global da dash
  const dias = TESTE_DAILY.filter(d => (!f0 || d.dateStr >= f0) && (!f1 || d.dateStr <= f1));

  // ── Totais do teste no período ──────────────────────────────────────────
  const inv     = dias.reduce((s,d) => s + d.custoAds, 0);
  const vendas  = dias.reduce((s,d) => s + d.vendas,   0);
  const receita = dias.reduce((s,d) => s + d.receita,  0);
  const vendUtm = dias.reduce((s,d) => s + (d.vendasUtm || 0), 0);
  const cac     = vendas > 0 && inv > 0 ? +(inv / vendas).toFixed(2) : null;
  // Lucro do teste: receita líquida de imposto (netFactor por dia = imposto do mês em Metas) − bureau ESTIMADO − ads
  const recLiq    = dias.reduce((s,d) => s + d.receita * netFactor(d.dateStr), 0);
  const bureauEst = vendas * P.bureauPorVenda;
  const lucro     = +(recLiq - bureauEst - inv).toFixed(2);
  const lucroVenda= vendas > 0 ? +(lucro / vendas).toFixed(2) : null;
  // Learning: conversões ACUMULADAS desde o início do teste (independe do filtro)
  const vendasAcum = TESTE_DAILY.reduce((s,d) => s + d.vendas, 0);
  const diasTeste  = TESTE_DAILY.length;

  // ── Bloco A: valores ────────────────────────────────────────────────────
  const st  = cacStatusTeste(cac);
  const el  = document.getElementById('ptCac');
  el.textContent = cac != null ? fmtR(cac) : '—';
  el.className   = 'produto-card-value ' + st.cls;
  const fase = document.getElementById('ptFaseBadge');
  if (!TESTE_DAILY.length) {
    // Estado vazio: sem série nenhuma (views pendentes ou campanha sem dados)
    fase.className = 'produto-badge'; fase.textContent = TESTE_WIRED ? '⏳ Sem vendas ainda' : '⏳ Aguardando setup';
  } else if (vendasAcum < P.learningConv) {
    fase.className = 'produto-badge'; fase.textContent = `🎓 Learning · ${vendasAcum}/${P.learningConv} conv.`;
  } else {
    fase.className = 'produto-badge ' + st.cls; fase.textContent = st.txt;
  }
  document.getElementById('ptMeta').textContent =
    dias.length ? `dia ${diasTeste} do teste · ${fmtN(vendas,0)} vendas no período`
    : TESTE_WIRED ? 'campanha ainda sem vendas/custo no período'
    : 'sem dados reais — views SQL pendentes';

  buildReguaTeste(cac);

  document.getElementById('ptMetrics').innerHTML = [
    { label:'Investimento', value:inv > 0 ? fmtR(inv) : '—',
      sub:dias.length ? fmtR(inv / dias.length) + '/dia' : '', cls:'' },
    { label:'Vendas', value:fmtN(vendas,0),
      sub:dias.length ? fmtN(vendas / dias.length,1) + '/dia' : '', cls:'' },
    { label:'Receita', value:receita > 0 ? fmtR(receita) : '—',
      sub:'ticket ' + fmtR(P.preco), cls:'' },
    { label:'Lucro/venda', value:lucroVenda != null ? fmtR(lucroVenda) : '—',
      sub:'líq. − bureau − CAC', cls:lucroVenda == null ? '' : lucroVenda >= 0 ? 'good' : 'danger' },
  ].map(m => `<div class="ads-bal-metric ${m.cls}">
      <div class="ads-bal-metric-label">${m.label}</div>
      <div class="ads-bal-metric-value">${m.value}</div>
      <div class="ads-bal-metric-sub">${m.sub}</div></div>`).join('');

  const utmPct = vendas > 0 ? vendUtm / vendas * 100 : null;
  // Padrão fixo pedido pelo usuário; bureau/venda já aparece na legenda da régua
  document.getElementById('ptAttrib').innerHTML = utmPct == null ? '' :
    `🔗 Cross-check de atribuição: <b>${fmtN(utmPct,0)}%</b> das vendas do produto com utm da campanha` +
    (utmPct < 90 ? ' <span class="warn">— verificar utm na LP</span>' : '');

  // ── Bloco B: funil atual = totais globais − teste ───────────────────────
  // Só subtrai com dados REAIS do teste (demo/sem-setup subtrairia números
  // falsos ou nada — nos dois casos o certo é mostrar os globais como estão).
  const desconta   = TESTE_WIRED && !TESTE_DEMO;
  const invAtual   = T.cost - (desconta ? inv     : 0);
  const vendAtual  = T.conv - (desconta ? vendas  : 0);
  const revAtual   = T.rev  - (desconta ? receita : 0);
  const netAtual   = T.netPftOpt - (desconta ? lucro : 0);
  const cacAtual   = vendAtual > 0 && invAtual > 0 ? +(invAtual / vendAtual).toFixed(2) : null;
  const elA = document.getElementById('paCac');
  elA.textContent = cacAtual != null ? fmtR(cacAtual) : '—';
  elA.className   = 'produto-card-value';
  document.getElementById('paCacSub').textContent = desconta
    ? 'CAC real do período · já descontado o teste'
    : TESTE_DEMO
      ? 'CAC real do período · teste (demo) NÃO descontado'
      : 'CAC real do período · teste ainda sem dados reais';
  document.getElementById('paMeta').textContent =
    `${fmtN(vendAtual,0)} pedidos pagos no período`;
  document.getElementById('paMetrics').innerHTML = [
    { label:'Investimento', value:invAtual > 0 ? fmtR(invAtual) : '—',
      sub:filtered.length ? fmtR(invAtual / filtered.length) + '/dia' : '', cls:'' },
    { label:'Vendas', value:fmtN(vendAtual,0),
      sub:filtered.length ? fmtN(vendAtual / filtered.length,1) + '/dia' : '', cls:'' },
    { label:'Receita/comprador', value:vendAtual > 0 ? fmtR(revAtual / vendAtual) : '—',
      sub:'inclui upsells', cls:'' },
    { label:'Lucro líq./comprador', value:vendAtual > 0 ? fmtR(netAtual / vendAtual) : '—',
      sub:'líq. − bureau − ads', cls:vendAtual > 0 && netAtual / vendAtual >= 0 ? 'good' : 'danger' },
  ].map(m => `<div class="ads-bal-metric ${m.cls}">
      <div class="ads-bal-metric-label">${m.label}</div>
      <div class="ads-bal-metric-value">${m.value}</div>
      <div class="ads-bal-metric-sub">${m.sub}</div></div>`).join('');

  // ── Gráficos: vendas (barras) + CAC (linha) ─────────────────────────────
  const lblT = ds => `${+ds.slice(8,10)}/${+ds.slice(5,7)}`;
  const cacSeries = dias.map(d => d.vendas > 0 && d.custoAds > 0 ? +(d.custoAds / d.vendas).toFixed(2) : null);
  mkChart('produtoTesteChart','bar', {
    labels: dias.map(d => lblT(d.dateStr)),
    datasets: [
      { label:'Vendas', data:dias.map(d => d.vendas), yAxisID:'y1',
        backgroundColor:'rgba(67,56,202,.45)', borderRadius:3, order:2 },
      { label:'CAC', data:cacSeries, type:'line', yAxisID:'y', order:1,
        borderColor:'#7c3aed', borderWidth:2, pointRadius:2.5, pointBackgroundColor:'#7c3aed',
        tension:.3, spanGaps:true },
      { label:'Meta ' + P.cacMetaMax, data:dias.map(() => P.cacMetaMax), type:'line', yAxisID:'y',
        borderColor:'rgba(22,163,74,.55)', borderDash:[4,3], borderWidth:1.5, pointRadius:0 },
      { label:'BE ' + P.cacBreakEven, data:dias.map(() => P.cacBreakEven), type:'line', yAxisID:'y',
        borderColor:'rgba(220,38,38,.5)', borderDash:[4,3], borderWidth:1.5, pointRadius:0 },
    ]
  }, {
    responsive:true, maintainAspectRatio:false,
    interaction:{ mode:'index', intersect:false },
    plugins:{
      legend:{ labels:{ font:{ size:10.5 }, boxWidth:9, padding:10 } },
      tooltip:{ callbacks:{ label:c => ' ' + c.dataset.label + ': ' +
        (c.dataset.label === 'Vendas' ? fmtN(c.raw,0) : fmtR(c.raw)) } },
      datalabels:{ display:false },
    },
    scales:{ x:{ grid:{ display:false }, ticks:{ font:{ size:9.5 }, maxTicksLimit:10 } },
             y:{ position:'left', grid:{ color:'rgba(0,0,0,.04)' }, ticks:{ font:{ size:9.5 }, callback:v => 'R$' + Math.round(v) } },
             y1:{ position:'right', grid:{ display:false }, ticks:{ font:{ size:9.5 }, precision:0 }, beginAtZero:true } }
  });

  const dAtual = filtered;
  mkChart('produtoAtualChart','bar', {
    labels: dAtual.map(lbl),
    datasets: [
      { label:'Vendas', data:dAtual.map(x => x.conv), yAxisID:'y1',
        backgroundColor:'rgba(37,99,235,.40)', borderRadius:3, order:2 },
      { label:'CAC', data:dAtual.map(x => x.cac), type:'line', yAxisID:'y', order:1,
        borderColor:'#0891b2', borderWidth:2, pointRadius:2, pointBackgroundColor:'#0891b2',
        tension:.3, spanGaps:true },
    ]
  }, {
    responsive:true, maintainAspectRatio:false,
    interaction:{ mode:'index', intersect:false },
    plugins:{
      legend:{ labels:{ font:{ size:10.5 }, boxWidth:9, padding:10 } },
      tooltip:{ callbacks:{ label:c => ' ' + c.dataset.label + ': ' +
        (c.dataset.label === 'Vendas' ? fmtN(c.raw,0) : fmtR(c.raw)) } },
      datalabels:{ display:false },
    },
    scales:{ x:{ grid:{ display:false }, ticks:{ font:{ size:9.5 }, maxTicksLimit:10 } },
             y:{ position:'left', grid:{ color:'rgba(0,0,0,.04)' }, ticks:{ font:{ size:9.5 }, callback:v => 'R$' + Math.round(v) } },
             y1:{ position:'right', grid:{ display:false }, ticks:{ font:{ size:9.5 }, precision:0 }, beginAtZero:true } }
  });
}

