  const labels = d.map(lbl);

  // 1. Revenue vs Cost — line, tooltips only (30 points too dense for labels)
  // Build projection for current month: extend chart with dashed estimate to month-end
  const _today = new Date();
  const _todayStr = `${_today.getFullYear()}-${String(_today.getMonth()+1).padStart(2,'0')}-${String(_today.getDate()).padStart(2,'0')}`;
  const _moStart  = _todayStr.slice(0,7)+'-01';
  const _inCurrMo = d.length >= 3 && d[0].dateStr >= _moStart && d[d.length-1].dateStr <= _todayStr;
  const _daysInMo   = new Date(_today.getFullYear(), _today.getMonth()+1, 0).getDate();
