    const _mo        = _today.getMonth()+1;
    for (let day = _today.getDate()+1; day <= _daysInMo; day++) {
      _projLabels.push(`${day}/${_mo}`);
      _projRevData.push(_avgRev);
      _projCostData.push(_avgCost);
