function mkChart(id, type, data, options) {
  if (charts[id]) { charts[id].destroy(); }
  charts[id] = new Chart(document.getElementById(id), { type, data, options,
    plugins:[ChartDataLabels] }); // attach plugin per-chart, not globally
}

// ─── TABLE ────────────────────────────────────────────────────────────────────
// HTML de uma linha de campanha — usado pela tabela principal e pela do Pacotão.
function campRowHtml(c, TGT, totalCostAllCamps) {
  // Campanha do teste R$79,90: barra/cor do CAC usam a régua do teste
  // (meta/empate/break-even), não a meta CAC do funil base (~R$9)
  const metaCac = c.teste ? PRODUTO_TESTE.cacMetaMax : TGT.cpa;
  const pct     = Math.min(100, Math.round((c.cac/metaCac)*100));
  const col     = c.teste
    ? (c.cac <= PRODUTO_TESTE.cacMetaMax ? '#16a34a' : c.cac <= PRODUTO_TESTE.cacBreakEven ? '#d97706' : '#dc2626')
    : (c.cac <= TGT.cpa ? '#16a34a' : '#dc2626');
  const spendPct = totalCostAllCamps > 0 ? fmtN((c.cost/totalCostAllCamps)*100,1)+'%' : '—';
  return `
      <td><span class="cname"><span class="dot" style="background:${c.color}"></span>${c.name}${c.teste?` <span class="camp-teste-chip">🧪 R$${fmtN(PRODUTO_TESTE.preco,2)}</span>`:''}</span></td>
      <td class="num">${fmtN(c.conv,1,'')}</td>
      <td class="num">${fmtR(c.cost)}</td>
      <td class="num" style="color:var(--text-secondary);font-weight:600">${spendPct}</td>
      <td class="num">${fmtN(c.roas,2,'')}×</td>
      <td><div class="bar-cell"><div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${col}"></div></div>
          <div style="display:flex;flex-direction:column;align-items:flex-end;min-width:46px">
            <span style="font-size:12px;font-variant-numeric:tabular-nums;color:${col};text-align:right">${fmtR(c.cac)}</span>
            ${c.cacAds>0?`<span style="font-size:10px;font-weight:300;color:var(--text-muted);text-align:right">Ads: ${fmtR(c.cacAds)}</span>`:''}
          </div></div></td>`;
}

function buildTable() {
  const allCamps = campTotals();
  // Teste Pacotão separado da tabela principal (ticket/régua diferentes);
  // % Gasto das duas tabelas usa o custo TOTAL (base + teste) como denominador.
  const camps      = allCamps.filter(c => !c.teste);
  const testeCamps = allCamps.filter(c =>  c.teste);
  const totalCostAllCamps = allCamps.reduce((s,c)=>s+c.cost, 0);

  // Sortable headers — init once, then just update arrow classes
  const thead = document.querySelector('#campaignTable thead tr');
  if (!thead.dataset.sortInit) {
    thead.dataset.sortInit = '1';
    thead.querySelectorAll('th').forEach((th, i) => {
      th.classList.add('sortable');
      th.addEventListener('click', () => {
        if (_campSort.col === i) _campSort.dir *= -1;
        else { _campSort.col = i; _campSort.dir = 1; }
        buildTable();
      });
    });
  }
  thead.querySelectorAll('th').forEach((th, i) => {
    th.classList.remove('sort-asc','sort-desc');
    if (i === _campSort.col) th.classList.add(_campSort.dir > 0 ? 'sort-asc' : 'sort-desc');
  });

  // Sort rows
  const sorted = [...camps];
  if (_campSort.col >= 0) {
    sorted.sort((a, b) => {
      if (_campSort.col === 0) return a.name.localeCompare(b.name) * _campSort.dir;
      const vals = [null, b=>b.conv, b=>b.cost, b=>b.cost, b=>b.roas, b=>b.cac];
      const fn = vals[_campSort.col]; if (!fn) return 0;
      return (fn(a) - fn(b)) * _campSort.dir;
    });
  }

  const maxCac = Math.max(...sorted.map(c=>c.cac));
  const TGT = activeTargets();
  const tbody = document.querySelector('#campaignTable tbody');
  tbody.innerHTML = '';
  sorted.forEach(c => {
    const tr = document.createElement('tr');
    tr.innerHTML = campRowHtml(c, TGT, totalCostAllCamps);
    tbody.appendChild(tr);
  });

  // ── Linha de totais ──────────────────────────────────────────────────────────
  const totConv    = sorted.reduce((s,c)=>s+c.conv, 0);
  const totGadsConv= sorted.reduce((s,c)=>s+(c.gadsConv||0), 0);
  const totCost = sorted.reduce((s,c)=>s+c.cost, 0);
  const totRev  = sorted.reduce((s,c)=>s+c.rev,  0);
  const totPft  = sorted.reduce((s,c)=>s+c.pft,  0);
  const totRoas = totCost > 0 ? +(totRev/totCost).toFixed(2) : 0;
  const totCac  = totConv > 0 ? +(totCost/totConv).toFixed(2) : 0;
  const totCacAds = totGadsConv > 0 ? +(totCost/totGadsConv).toFixed(2) : 0;
  const totCol  = totCac <= TGT.cpa ? '#16a34a' : '#dc2626';
  const tfoot = document.createElement('tr');
  tfoot.className = 'tr-total';
  tfoot.innerHTML = `
    <td>Total</td>
    <td class="num">${fmtN(totConv,1,'')}</td>
    <td class="num">${fmtR(totCost)}</td>
    <td class="num">${totalCostAllCamps > 0 ? fmtN(totCost/totalCostAllCamps*100,1)+'%' : '—'}</td>
    <td class="num">${fmtN(totRoas,2,'')}×</td>
    <td><div style="display:flex;flex-direction:column;align-items:flex-end">
          <span style="font-size:12px;font-variant-numeric:tabular-nums;color:${totCol}">${fmtR(totCac)}</span>
          ${totCacAds>0?`<span style="font-size:10px;font-weight:300;color:var(--text-muted)">Ads: ${fmtR(totCacAds)}</span>`:''}
        </div></td>`;
  tbody.appendChild(tfoot);

  // ── Tabela separada da campanha do teste (Pacotão) ─────────────────────────
  const pacSection = document.getElementById('pacotaoSection');
  const pacBody    = document.querySelector('#pacotaoTable tbody');
  if (pacSection && pacBody) {
    pacBody.innerHTML = '';
    if (!testeCamps.length) {
      pacSection.style.display = 'none';
    } else {
      pacSection.style.display = '';
      testeCamps.forEach(c => {
        const tr = document.createElement('tr');
        tr.innerHTML = campRowHtml(c, TGT, totalCostAllCamps);
        pacBody.appendChild(tr);
      });
    }
  }
}

// ─── LOST IMPRESSION SHARE ────────────────────────────────────────────────────
// Métricas de IS (impression_share, budget_lost_is, rank_lost_is) só existem
// para campanhas Search (NULL nas demais — Shopping/PMax/Display são ignoradas
// aqui). "Eligible impressions" é derivado por dia/campanha: impressions ÷ IS
// (quando IS > 0) — não dá pra somar IS diretamente entre dias/campanhas.
function lostIsRowsInRange(minDate, maxDate) {
  return CAMPAIGN_DAILY_DATA.filter(r =>
    r.dateStr >= minDate && r.dateStr <= maxDate && r.searchIS != null && r.searchIS > 0);
}
function lostIsRows() {
  if (!filtered.length) return [];
  return lostIsRowsInRange(filtered[0].dateStr, filtered[filtered.length-1].dateStr);
}
// Agrega linhas cruas por campanha-base, retornando eligible/impr/lost/conv/cost acumulados.
function aggLostIsByCamp(rows) {
  const byCamp = new Map();
  for (const r of rows) {
    const base = BASE_CAMPS.find(c => r.campaign.includes(c.name));
    const key = base ? base.name : r.campaign;
    const eligible = r.impressions / r.searchIS;
    const prev = byCamp.get(key) || { name:key, color: CAMP_COLORS[key] || '#6b6b6b', cost:0, eligible:0, impr:0, lostBudget:0, lostRank:0, conv:0 };
    prev.cost       += r.cost;
    prev.eligible   += eligible;
    prev.impr       += r.impressions;
    prev.lostBudget += eligible * (r.budgetLostIS || 0);
    prev.lostRank   += eligible * (r.rankLostIS   || 0);
    prev.conv       += r.conversions || 0;
    byCamp.set(key, prev);
  }
  return byCamp;
}
// Agregado geral (soma de todas as campanhas) — usado pra árvore de diagnóstico.
function aggLostIsTotal(rows) {
  const byCamp = aggLostIsByCamp(rows);
  const camps = Array.from(byCamp.values());
  const eligible = camps.reduce((s,c)=>s+c.eligible, 0);
  const impr     = camps.reduce((s,c)=>s+c.impr, 0);
  const lostBudget = camps.reduce((s,c)=>s+c.lostBudget, 0);
  const lostRank   = camps.reduce((s,c)=>s+c.lostRank, 0);
  return {
    isPct:     eligible > 0 ? impr / eligible : 0,
    budgetPct: eligible > 0 ? lostBudget / eligible : 0,
    rankPct:   eligible > 0 ? lostRank / eligible : 0,
  };
}

function buildLostIS(T) {
  const rows = lostIsRows();
  const ticket = T && T.ticket > 0 ? T.ticket : MONTHLY.revenue / MONTHLY.conv; // fallback se sem pedidos no período

  // ── Agregado por campanha (tabela) — inclui estimativa de conv./R$ perdidos ──
  const byCamp = aggLostIsByCamp(rows);
  const campRows = Array.from(byCamp.values()).map(c => {
    const is        = c.eligible > 0 ? c.impr       / c.eligible : 0;
    const budgetPct = c.eligible > 0 ? c.lostBudget / c.eligible : 0;
    const rankPct   = c.eligible > 0 ? c.lostRank   / c.eligible : 0;
    // Taxa de conversão por impressão real recebida (conversões do Ads ÷ impressões reais).
    // Aplicada às impressões perdidas pra estimar quanto teria convertido se elas tivessem existido.
    // É uma aproximação — assume que impressão adicional converteria na mesma taxa da atual.
    const convRate     = c.impr > 0 ? c.conv / c.impr : 0;
    const lostConv      = (c.lostBudget + c.lostRank) * convRate;
    const lostConvBudget= c.lostBudget * convRate;
    const lostConvRank  = c.lostRank   * convRate;
    const lostRev        = lostConv * ticket;
    return { ...c, is, budgetPct, rankPct, convRate, lostConv, lostConvBudget, lostConvRank, lostRev };
  }).sort((a,b) => b.lostRev - a.lostRev);

  // Campanhas com custo no período mas SEM Impression Share reportado — o Google
  // só devolve search_impression_share com volume/histórico suficiente, então
  // campanha recém-criada (ex.: PACOTAO em learning) não tem IS nos primeiros
  // dias. Antes elas simplesmente não apareciam aqui; agora entram com "—" nas
  // colunas de IS, com o custo visível.
  const semIS = (() => {
    if (!filtered.length) return [];
    const minD = filtered[0].dateStr, maxD = filtered[filtered.length-1].dateStr;
    const agg = new Map();
    for (const r of CAMPAIGN_DAILY_DATA) {
      if (r.dateStr < minD || r.dateStr > maxD || !(r.cost > 0)) continue;
      const base = BASE_CAMPS.find(c => r.campaign.includes(c.name));
      const key = base ? base.name : r.campaign;
      if (byCamp.has(key)) continue; // já tem linhas com IS no período
      const prev = agg.get(key) || { name:key, color: CAMP_COLORS[key] || '#6b6b6b', cost:0 };
      prev.cost += r.cost;
      agg.set(key, prev);
    }
    return Array.from(agg.values()).sort((a,b) => b.cost - a.cost);
  })();

  const tbody = document.querySelector('#lostIsTable tbody');
  if (tbody) {
    tbody.innerHTML = '';
    if (!campRows.length && !semIS.length) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;color:var(--text-muted);padding:16px;font-size:12.5px">Sem dados de Impression Share no período (aguardando sync)</td></tr>';
    } else {
      campRows.forEach(c => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td><span class="cname"><span class="dot" style="background:${c.color}"></span>${c.name}</span></td>
          <td class="num" style="color:var(--red);font-weight:600">${fmtN(c.budgetPct*100,0)}%</td>
          <td class="num" style="color:var(--accent);font-weight:600">${fmtN(c.rankPct*100,0)}%</td>
          <td class="num">${fmtR(c.cost)}</td>
          <td class="num" style="color:var(--green);font-weight:600">${fmtN(c.is*100,0)}%</td>
          <td class="num" title="Budget: ${fmtN(c.lostConvBudget,1)} · Rank: ${fmtN(c.lostConvRank,1)}">${fmtN(c.lostConv,1)}</td>
          <td class="num" style="color:var(--red);font-weight:600">${fmtR(c.lostRev)}</td>`;
        tbody.appendChild(tr);
      });
      semIS.forEach(c => {
        const tr = document.createElement('tr');
        const dash = '<td class="num" style="color:var(--text-muted)">—</td>';
        tr.innerHTML = `
          <td><span class="cname" title="Google ainda não reporta Impression Share pra esta campanha (volume/histórico insuficiente)"><span class="dot" style="background:${c.color}"></span>${c.name} <span style="font-size:10px;color:var(--text-muted)">IS pendente</span></span></td>
          ${dash}${dash}
          <td class="num">${fmtR(c.cost)}</td>
          ${dash}${dash}${dash}`;
        tbody.appendChild(tr);
      });
    }
  }

  // ── Card de maior oportunidade ─────────────────────────────────────────────
  const opp = document.getElementById('lostIsOpp');
  if (opp) {
    const top = campRows[0];
    if (!top || top.lostRev <= 0) {
      opp.style.display = 'none';
    } else {
      const causa = top.lostConvBudget >= top.lostConvRank ? 'orçamento' : 'rank/qualidade do anúncio';
      opp.style.display = 'flex';
      opp.innerHTML = `<span class="lost-is-opp-emoji">🔴</span><span class="lost-is-opp-text">Maior oportunidade do período: <b>${top.name}</b> deixou de faturar
        ~${fmtR(top.lostRev)} (${fmtN(top.lostConv,1)} conversões aprox.), principalmente por <b>${causa}</b>.</span>`;
    }
  }

  // ── Árvore de diagnóstico (agregado geral, ponderado por impressões elegíveis) ──
  const curr = aggLostIsTotal(rows);
  const lostPct = 1 - curr.isPct;

  // Período anterior de mesmo tamanho (mesmo padrão de prevTotals()).
  let prevDelta = null;
  if (filtered.length) {
    const n = filtered.length, minDate = filtered[0].dateStr;
    const prevDays = ALL_DAYS.filter(d => d.dateStr < minDate).slice(-n);
    if (prevDays.length) {
      const prevRows = lostIsRowsInRange(prevDays[0].dateStr, prevDays[prevDays.length-1].dateStr);
      if (prevRows.length) {
        const prev = aggLostIsTotal(prevRows);
        prevDelta = {
          is:     pctDelta(curr.isPct,     prev.isPct,     false), // IS subir é bom
          budget: pctDelta(curr.budgetPct, prev.budgetPct, true),  // perda subir é ruim
          rank:   pctDelta(curr.rankPct,   prev.rankPct,   true),
        };
      }
    }
  }
  const deltaHtml = d => d ? `<span class="lit-delta ${d.cls}">${d.txt}</span>` : '';

  const tree = document.getElementById('lostIsTree');
  if (tree) {
    if (!campRows.length) {
      tree.innerHTML = '<div style="text-align:center;color:var(--text-muted);font-size:12.5px;padding:16px">Sem dados no período</div>';
    } else {
      tree.innerHTML = `
        <div class="lit-row">
          <div class="lit-box lit-is"><div class="lit-pct">${fmtN(curr.isPct*100,0)}%</div><div class="lit-label">Impression Share</div>${deltaHtml(prevDelta && prevDelta.is)}</div>
          <div class="lit-box lit-lost"><div class="lit-pct">${fmtN(lostPct*100,0)}%</div><div class="lit-label">Lost Impression Share</div></div>
        </div>
        <div class="lit-connector"></div>
        <div class="lit-row">
          <div class="lit-box lit-budget"><div class="lit-pct">${fmtN(curr.budgetPct*100,0)}%</div><div class="lit-label">Perdido por orçamento</div>${deltaHtml(prevDelta && prevDelta.budget)}</div>
          <div class="lit-box lit-rank"><div class="lit-pct">${fmtN(curr.rankPct*100,0)}%</div><div class="lit-label">Perdido por rank</div>${deltaHtml(prevDelta && prevDelta.rank)}</div>
        </div>`;
      equalizeCardHeights('#lostIsTree', '.lit-box', { always: true });
    }
  }

  // ── Donut: share de investimento entre campanhas Search ───────────────────
  const totCostSearch = campRows.reduce((s,c)=>s+c.cost, 0);
  mkChart('lostIsShareChart', 'doughnut', {
    labels: campRows.map(c=>c.name),
    datasets: [{ data: campRows.map(c=>c.cost), backgroundColor: campRows.map(c=>c.color) }],
  }, {
    responsive:true, maintainAspectRatio:false,
    plugins: { legend:{position:'right', labels:{boxWidth:10,font:{size:10.5}}},
      datalabels: { color:'#fff', font:{size:10,weight:'700'},
        formatter: v => totCostSearch>0 ? fmtN(v/totCostSearch*100,1)+'%' : '' } },
  });

  // ── Line chart: evolução diária Lost IS budget vs rank ────────────────────
  const byDate = new Map();
  for (const r of rows) {
    const eligible = r.impressions / r.searchIS;
    const prev = byDate.get(r.dateStr) || { eligible:0, lostBudget:0, lostRank:0 };
    prev.eligible   += eligible;
    prev.lostBudget += eligible * (r.budgetLostIS || 0);
    prev.lostRank   += eligible * (r.rankLostIS   || 0);
    byDate.set(r.dateStr, prev);
  }
  const dates = Array.from(byDate.keys()).sort();
  mkChart('lostIsEvolutionChart', 'line', {
    labels: dates.map(fmt2),
    datasets: [
      { label:'Search Lost IS (budget)', data: dates.map(d=>{ const v=byDate.get(d); return v.eligible>0?+(v.lostBudget/v.eligible*100).toFixed(1):0; }),
        borderColor:'#dc2626', backgroundColor:'#dc2626', tension:.3, pointRadius:0, borderWidth:2 },
      { label:'Search Lost IS (rank)', data: dates.map(d=>{ const v=byDate.get(d); return v.eligible>0?+(v.lostRank/v.eligible*100).toFixed(1):0; }),
        borderColor:'#2563eb', backgroundColor:'#2563eb', tension:.3, pointRadius:0, borderWidth:2 },
    ],
  }, {
    responsive:true, maintainAspectRatio:false,
    scales: { y: { min:0, max:100, ticks:{ callback:v=>v+'%' } } },
    plugins: { legend:{position:'top', labels:{boxWidth:10,font:{size:10.5}}}, datalabels:{display:false} },
  });

  // "Lost Impressions por Campanha" + "Lost Impressions — Causa": no mobile já
  // empilham (grid-1-1 vira 1 coluna), aqui só igualamos a altura das duas.
  equalizeCardHeights('#view-campanhas .grid-1-1', '.card');
}

// ─── UPSELL TYPE TABLE ───────────────────────────────────────────────────────
function buildUpsellTypeTable() {
  const tbody = document.querySelector('#upsellTypeTable tbody');
  tbody.innerHTML = '';

  // Determine date range from current filter
  const dates = filtered.map(d => d.dateStr);
  if (!dates.length) {
    tbody.innerHTML = '<tr><td colspan="4" style="text-align:center;color:var(--text-muted);padding:16px;font-size:12.5px">Sem dados no período selecionado</td></tr>';
    return;
  }
  const minDate = dates[0], maxDate = dates[dates.length - 1];

  // Aggregate UPSELL_TYPE_DATA for the period
  const agg = new Map(); // addonKey → { label, count, revenue }
  for (const row of UPSELL_TYPE_DATA) {
    if (row.dateStr < minDate || row.dateStr > maxDate) continue;
    if (!agg.has(row.addonKey)) agg.set(row.addonKey, { label: row.label, count: 0, revenue: 0 });
    const e = agg.get(row.addonKey);
    e.count   += row.count;
    e.revenue += row.revenue;
  }

  // Trend: compare 1st half vs 2nd half of the filtered period
  const midDate = dates[Math.floor(dates.length / 2)];
  const agg1 = new Map(), agg2 = new Map(); // first/second half counts
  for (const row of UPSELL_TYPE_DATA) {
    if (row.dateStr < minDate || row.dateStr > maxDate) continue;
    const map = row.dateStr < midDate ? agg1 : agg2;
    const prev = map.get(row.addonKey) || 0;
    map.set(row.addonKey, prev + row.count);
  }
  const trendIcon = key => {
    const c1 = agg1.get(key) || 0, c2 = agg2.get(key) || 0;
    if (c1 + c2 < 2) return { icon:'→', color:'var(--text-muted)' };
    const delta = c1 > 0 ? (c2 - c1) / c1 * 100 : 0;
    if (delta > 8)  return { icon:'↑', color:'var(--green)' };
    if (delta < -8) return { icon:'↓', color:'var(--red)' };
    return { icon:'→', color:'var(--text-muted)' };
  };

  if (!agg.size) {
    // Fallback: use existing aggregated upsell data from filtered days
    const totalUpsell = filtered.reduce((s, d) => s + (d.pedidosUpsell || 0), 0);
    if (!totalUpsell) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;color:var(--text-muted);padding:16px;font-size:12.5px">Configure UPSELL_TYPE_URL para ver breakdown por tipo</td></tr>';
      return;
    }
    // Show single "Upsell" row with totals from main CSV
    const totalRevUpsell = filtered.reduce((s, d) => s + (d.revenueUpsell || 0), 0);
    const totalOrders = filtered.reduce((s, d) => s + (d.pedidos || 0), 0);
    tbody.innerHTML = `<tr>
      <td style="font-weight:500">Upsell (todos os tipos)</td>
      <td class="num">${totalUpsell}</td>
      <td class="num" style="color:var(--text-muted)">→</td>
      <td class="num">${totalOrders ? ((totalUpsell/totalOrders)*100).toFixed(1)+'%' : '—'}</td>
      <td class="num">${totalRevUpsell ? fmtR(totalRevUpsell) : '—'}</td>
    </tr>`;
    return;
  }

  const totalCount = Array.from(agg.values()).reduce((s, e) => s + e.count, 0);
  let rows = Array.from(agg.entries())
    .map(([key, e]) => ({ key, ...e }));

  // Sortable headers for upsell table — init once
  const uThead = document.querySelector('#upsellTypeTable thead tr');
  if (!uThead.dataset.sortInit) {
    uThead.dataset.sortInit = '1';
    uThead.querySelectorAll('th').forEach((th, i) => {
      th.classList.add('sortable');
      th.addEventListener('click', () => {
        if (_upsellSort.col === i) _upsellSort.dir *= -1;
        else { _upsellSort.col = i; _upsellSort.dir = 1; }
        buildUpsellTypeTable();
      });
    });
  }
  uThead.querySelectorAll('th').forEach((th, i) => {
    th.classList.remove('sort-asc','sort-desc');
    if (i === _upsellSort.col) th.classList.add(_upsellSort.dir > 0 ? 'sort-asc' : 'sort-desc');
  });

  if (_upsellSort.col >= 0) {
    rows.sort((a, b) => {
      if (_upsellSort.col === 0) return a.label.localeCompare(b.label) * _upsellSort.dir;
      const fns = [null, r=>r.count, r=>{ const t=trendIcon(r.key); return t.icon==='↑'?1:t.icon==='↓'?-1:0; }, r=>r.count/totalCount, r=>r.revenue];
      const fn = fns[_upsellSort.col]; if (!fn) return 0;
      return (fn(a) - fn(b)) * _upsellSort.dir;
    });
  } else {
    rows.sort((a, b) => b.count - a.count); // default: by count desc
  }

  rows.forEach(r => {
    const pct = totalCount ? ((r.count / totalCount) * 100).toFixed(1) : '0.0';
    const t   = trendIcon(r.key);
    const tr  = document.createElement('tr');
    tr.innerHTML = `
      <td style="font-weight:500">${r.label}</td>
      <td class="num">${r.count}</td>
      <td class="num tendencia-col" style="color:${t.color};font-size:14px;font-weight:700">${t.icon}</td>
      <td class="num" style="color:#7c3aed;font-weight:600">${pct}%</td>
      <td class="num"><span class="trend-in-receita" style="color:${t.color}">${t.icon} </span>${fmtR(r.revenue)}</td>`;
    tbody.appendChild(tr);
  });

  // Totals row
  const totalRevenue = rows.reduce((s, r) => s + r.revenue, 0);
  const tfoot = document.createElement('tr');
  tfoot.className = 'tr-total';
  tfoot.innerHTML = `<td>Total</td><td class="num">${totalCount}</td><td class="num tendencia-col"></td><td class="num">100%</td><td class="num">${fmtR(totalRevenue)}</td>`;
  tbody.appendChild(tfoot);

  // Upsell pie chart — distribuição por tipo
  const _pieColors = ['#2563eb','#7c3aed','#0891b2','#d97706','#dc2626','#16a34a','#db2777','#ea580c','#65a30d'];
  mkChart('upsellPieChart', 'doughnut', {
    labels: rows.map(r => r.label),
    datasets:[{
      data: rows.map(r => r.count),
      backgroundColor: rows.map((_, i) => _pieColors[i % _pieColors.length]),
      borderWidth: 1, borderColor: '#fff', hoverOffset: 6
    }]
  },{
    responsive:true, maintainAspectRatio:false,
    plugins:{
      legend:{ position:'bottom', labels:{ font:{size:10}, boxWidth:10, padding:8 } },
      tooltip:{ callbacks:{ label: c => ` ${c.label}: ${c.raw} (${totalCount>0?((c.raw/totalCount)*100).toFixed(1):0}%)` } },
      datalabels:{
        display: ctx => ctx.dataset.data[ctx.dataIndex] / totalCount >= 0.06,
        formatter: (v) => totalCount > 0 ? ((v/totalCount)*100).toFixed(0)+'%' : '',
        color:'#fff', font:{ size:10, weight:'700' }
      }
    }
  });
}

// ─── CONVERSION FUNNEL ───────────────────────────────────────────────────────
function buildFunnel() {
  const wrap = document.getElementById('funnelWrap');
  wrap.innerHTML = '';
  if (!filtered.length) return;

  const T = totals();
  const checkouts    = filtered.reduce((s,d) => s+(d.checkouts||0), 0);
  const pedidos      = filtered.reduce((s,d) => s+(d.conv||0),      0);
  const pedUpsell    = filtered.reduce((s,d) => {
    const u = d.pedidosUpsell != null ? d.pedidosUpsell : Math.round((d.conv||0)*((d.upsellRate||0)/100));
    return s + u;
  }, 0);

  const base = checkouts > 0 ? checkouts : pedidos; // use checkouts as base, fallback to pedidos
  if (!base) return;

  const convRate   = checkouts > 0 ? (pedidos   / checkouts * 100) : null;
  const upsellRate = pedidos   > 0 ? (pedUpsell / pedidos   * 100) : null;

  const steps = [
    { label:'Checkouts', count: Math.round(checkouts), color:'#2563eb',
      pct: 100, rateTxt: convRate != null ? `↓ Conv: ${convRate.toFixed(1)}% → Pedidos` : null },
    { label:'Pedidos',   count: Math.round(pedidos),   color:'#16a34a',
      pct: base > 0 ? (pedidos   / base * 100) : 0,
      rateTxt: upsellRate != null ? `↓ Upsell: ${upsellRate.toFixed(1)}% → Add-ons` : null },
    { label:'Upsells',   count: Math.round(pedUpsell), color:'#7c3aed',
      pct: base > 0 ? (pedUpsell / base * 100) : 0,
      rateTxt: null },
  ];

  steps.forEach((step, i) => {
    // Bar row
    const row = document.createElement('div');
    row.className = 'funnel-row';
    const barW = Math.max(Math.min(step.pct, 100), 4); // clamp 4–100%
    const subTxt = i === 0 ? 'topo do funil'
                 : i === 1 ? (convRate != null ? `${convRate.toFixed(1)}% dos checkouts` : '% de checkouts')
                 :            (upsellRate != null ? `${upsellRate.toFixed(1)}% dos pedidos` : '% dos pedidos');
    row.innerHTML = `
      <div class="funnel-lbl">${step.label}</div>
      <div class="funnel-bar-col">
        <div class="funnel-bar" style="width:${barW}%;background:${step.color}">
          <span class="funnel-bar-val">${step.pct >= 12 ? fmtN(step.count,0,'') : ''}</span>
        </div>
      </div>
      <div class="funnel-stats">
        <div class="funnel-count">${fmtN(step.count,0,'')}</div>
        <div class="funnel-pct">${subTxt}</div>
      </div>`;
    wrap.appendChild(row);

    // Connector between steps
    if (step.rateTxt) {
      const conn = document.createElement('div');
      conn.className = 'funnel-connector';
      conn.innerHTML = `
        <div class="funnel-arrow-col"><div class="funnel-v-line"></div></div>
        <span class="funnel-rate-txt">${step.rateTxt}</span>`;
      wrap.appendChild(conn);
    }
  });
}

// ─── DATA FRESHNESS ──────────────────────────────────────────────────────────
function buildFreshness() {
  const dot   = document.getElementById('freshDot');
  const lbl   = document.getElementById('lastUpdated');
  if (!dot || !lbl) return;
  if (!ALL_DAYS.length) { dot.className='fresh-dot amber'; lbl.textContent='Sem dados'; return; }

  const lastDateStr = ALL_DAYS[ALL_DAYS.length-1].dateStr;
  const now         = new Date();
  const pad         = n => String(n).padStart(2,'0');
  const todayStr    = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
  const yesterStr   = (() => { const d=new Date(now); d.setDate(d.getDate()-1);
                               return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();

  let dotClass, msg;
  if (lastDateStr === todayStr) {
    dotClass = 'green';
    msg = 'Dados de hoje · carregado ' + now.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
  } else if (lastDateStr === yesterStr) {
    dotClass = 'amber';
    msg = 'Último dado: ontem (' + fmt2(lastDateStr) + ') · aguardando sync';
  } else {
    dotClass = 'red';
    msg = 'Último dado: ' + fmt2(lastDateStr) + ' · dados desatualizados';
  }
  dot.className = 'fresh-dot ' + dotClass;
  lbl.textContent = msg;
}

