function buildTodayPace() {
  const wrap  = document.getElementById('todayPace');
  if (!wrap) return;

  const now     = new Date();
  const pad     = n => String(n).padStart(2,'0');
  const todayStr= `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
  const isToday = activePreset === 'today';
  wrap.style.display = isToday ? 'block' : 'none';
  if (!isToday) return;

  // Hoje pode não ter dados ainda (sync pendente) — usa objeto zerado
  const today = filtered.length > 0 && filtered[0].dateStr === todayStr
    ? filtered[0]
    : { dateStr: todayStr, revenue: 0, cost: 0, costBureau: 0, costTotal: 0, profit: 0, conv: 0, cac: 0 };

  // Média dos últimos 30 dias (excluindo hoje)
  const past   = ALL_DAYS.filter(d => d.dateStr < todayStr).slice(-30);
  const avgRev    = past.length ? past.reduce((s,d)=>s+d.revenue,0)/past.length : 0;
  const avgCost   = past.length ? past.reduce((s,d)=>s+(d.costTotal||0),0)/past.length : 0;
  const avgConv   = past.length ? past.reduce((s,d)=>s+d.conv,0)/past.length : 0;
  const avgProfit = past.length ? past.reduce((s,d)=>s+(d.profit||0),0)/past.length : 0;

  // Fração do dia decorrida (horário de Brasília aproximado pelo navegador)
  const hourFrac   = (now.getHours()*60 + now.getMinutes()) / 1440;
  const expectedRev= avgRev * hourFrac;
  const paceRatio  = expectedRev > 0 ? today.revenue / expectedRev : null;
  const paceColor  = paceRatio === null ? 'var(--text-muted)' : paceRatio >= 0.9 ? 'var(--green)' : paceRatio >= 0.7 ? 'var(--amber)' : 'var(--red)';
  const paceTxt    = paceRatio === null ? '—' : (paceRatio >= 0.9 ? '✓ No ritmo' : paceRatio >= 0.7 ? '⚠ Abaixo do ritmo' : '↓ Bem abaixo');

  // Projeção EOD (end of day)
